# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.uneven_ground_ball.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os,sys\nfrom pathlib import Path\n\nROOT=_PCVE_ROOT\n_dll_handles=[]\nif os.name=='nt':\n    directory=Path(sys.prefix)/'Library/bin'\n    if directory.exists():_dll_handles.append(os.add_dll_directory(str(directory)))\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_support.uneven_ground_ball.scene_config": "\"\"\"A ball rolling over a rutted, sloping earth path. SI units.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport math\n\nSCENE_NAME='uneven_ground_ball'\nTOTAL_FRAMES=72\n# Low, near-grazing three-quarter view: the horizon line sits close to the ball,\n# so every crest and hollow of the path breaks the silhouette instead of being\n# flattened into a top-down texture.\nTERRAIN_CAMERA=dict(location=[-0.50,-2.20,.66],target=[-0.50,-.10,.10],lens_mm=26)\nBASELINE_PHYSICS=dict(gravity=[0,0,-9.81],ball_radius=.10,ball_mass=.45,ball_speed=1.4,ball_inertia_factor=.64,\n    ball_start_xy=[-1.8,-.20],ball_friction=.35,ball_rolling_friction=.0015,\n    ball_restitution=.05,ground_friction=1.,substeps=40,solver_iterations=100,\n    terrain_bounds=[[-8.,-8.],[12.,8.]],terrain_cells=[400,320],\n    terrain_base_height=.08,terrain_slope=-.016,terrain_roughness=1.,    # cx, cy, amplitude, sigma_x, sigma_y. Negative amplitude is a hollow.\n    # A broad worn trough carries the ball along +x; discrete mounds and hollows\n    # inside and beside it make the path wander without throwing the ball off it.\n    bumps=[[-.30,-.30,-.040,2.40,.50],\n           [.90,-.50,-.045,.340,.300],\n           [.60,.25,.045,.400,.300],\n           [-1.20,-.45,-.040,.300,.280],\n           [1.80,-.20,.040,.400,.340]])\n\ndef defaults():\n    return dict(schema_version=1,scene=SCENE_NAME,physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24,duration_sec=3.,slow_motion=1,resolution=[960,540],samples=16),\n        camera=dict(location=[-0.55,-2.95,3.6],target=[.75,-.15,.1],lens_mm=35))\n\ndef merge(base,overrides):\n    result=deepcopy(base)\n    for key,value in overrides.items():result[key]=merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\ndef validate(s):\n    if set(s)-{'schema_version','scene','physics','render','camera','seed'}:raise ValueError('Unknown scenario field; nest physics overrides under physics')\n    c=s['physics'];r=s['render']\n    if set(c)-set(BASELINE_PHYSICS):raise ValueError('Unknown physics parameter')\n    for key in ('ball_radius','ball_mass','ball_inertia_factor','ground_friction','substeps','solver_iterations'):\n        if not math.isfinite(c[key]) or c[key]<=0:raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_speed','ball_friction','ball_rolling_friction','terrain_roughness'):\n        if not math.isfinite(c[key]) or c[key]<0:raise ValueError(f'{key} must be nonnegative and finite')\n    if not 0<=c['ball_restitution']<=1:raise ValueError('Invalid restitution')\n    if len(c['gravity'])!=3 or not all(math.isfinite(v) for v in c['gravity']):raise ValueError('Invalid gravity')\n    lo,hi=c['terrain_bounds']\n    if len(lo)!=2 or len(hi)!=2 or any(not math.isfinite(v) for v in lo+hi) or any(a>=b for a,b in zip(lo,hi)):raise ValueError('Invalid ground bounds')\n    if len(c['terrain_cells'])!=2 or any(n<2 or n!=int(n) for n in c['terrain_cells']):raise ValueError('Invalid terrain discretization')\n    if len(c['ball_start_xy'])!=2 or any(not a+c['ball_radius']<v<b-c['ball_radius'] for a,b,v in zip(lo,hi,c['ball_start_xy'])):raise ValueError('Ball starts outside terrain')\n    for bump in c['bumps']:\n        if len(bump)!=5 or not all(math.isfinite(v) for v in bump) or min(bump[3:])<=0:raise ValueError('Invalid terrain bump')\n    if r['fps']<=0 or r['duration_sec']<=0 or r['slow_motion'] not in (1,2,4,8) or c['substeps']%r['slow_motion']:raise ValueError('Invalid sampling or slow motion')\n", "scene_support.uneven_ground_ball.scene_environment": "\"\"\"Courtyard environment and physically based ground shading.\n\nThe ground is the simulation mesh itself: nothing here moves a vertex. Real\nmaterial response (albedo, roughness, normal, ambient occlusion) comes from CC0\nPoly Haven texture sets, which supply exactly the sub-centimetre relief the 5 cm\ncollision grid cannot carry. When a texture set is missing the material degrades\nto the earlier procedural look instead of failing.\n\nThree physics-neutral cues make the undulation read:\n  1. a low raking sun, so every crest throws a shadow into the trough beside it,\n  2. baked cavity/slope tint from the height field itself (dust settles in\n     hollows, crests are scuffed bare),\n  3. normal and displacement maps at sub-mesh scale.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport json,math,random\n\nHERE=_PCVE_ROOT/'assets'/'polyhaven'/'uneven_ground_ball'\n# Same location and naming as the other scenes in /scripts: <asset>_<channel>_<res>.jpg\nASSETS=HERE\nPATH_TEXTURE='floor_pebbles_01'\nGRASS_TEXTURE='grass_ground'\nRESOLUTION='2k'\nCHANNELS=('diff','disp','nor_gl','rough','ao')\n\ndef material(bpy,name,color,metal=0,roughness=.5):\n    mat=bpy.data.materials.new(name);mat.diffuse_color=(*color,1);mat.use_nodes=True\n    shader=mat.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Base Color'].default_value=(*color,1);shader.inputs['Metallic'].default_value=metal;shader.inputs['Roughness'].default_value=roughness\n    return mat\n\ndef wood(bpy,name,light=(.40,.24,.115),dark=(.20,.095,.038)):\n    mat=material(bpy,name,light,roughness=.48);nodes=mat.node_tree.nodes;links=mat.node_tree.links\n    coords=nodes.new('ShaderNodeTexCoord');scale=nodes.new('ShaderNodeVectorMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=(2,95,5)\n    links.new(coords.outputs['Generated'],scale.inputs[0]);noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=2.5;noise.inputs['Detail'].default_value=3\n    links.new(scale.outputs[0],noise.inputs['Vector']);ramp=nodes.new('ShaderNodeValToRGB');ramp.color_ramp.elements[0].color=(*dark,1);ramp.color_ramp.elements[1].color=(*light,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0]);shader=nodes.get('Principled BSDF');links.new(ramp.outputs['Color'],shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.16;bump.inputs['Distance'].default_value=.0007\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal']);return mat\n\ndef box(bpy,name,location,size,mat,pitch=0,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=location);obj=bpy.context.object;obj.name=name;obj.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True);obj.rotation_euler[1]=pitch;obj.data.materials.append(mat)\n    if bevel:\n        mod=obj.modifiers.new('Manufactured edge','BEVEL');mod.width=bevel;mod.segments=3;obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef load_texture_set(bpy,asset,resolution=RESOLUTION):\n    \"\"\"Return {channel: bpy.types.Image} for a fetched Poly Haven set, or {}.\"\"\"\n    images={}\n    for channel in CHANNELS:\n        path=ASSETS/f'{asset}_{channel}_{resolution}.jpg'\n        if not path.exists():continue\n        image=bpy.data.images.load(str(path),check_existing=True)\n        image.colorspace_settings.name='sRGB' if channel=='diff' else 'Non-Color'\n        images[channel]=image\n    return images\n\ndef _mix(nodes,links,factor,first,second,blend='MIX'):\n    \"\"\"MixRGB that accepts either a socket, an RGB tuple, or a numeric factor.\"\"\"\n    node=nodes.new('ShaderNodeMixRGB');node.blend_type=blend\n    if isinstance(factor,(int,float)):node.inputs[0].default_value=factor\n    else:links.new(factor,node.inputs[0])\n    for source,index in ((first,1),(second,2)):\n        if isinstance(source,tuple):\n            node.inputs[index].default_value=tuple(source)+(1.,)*(4-len(source)) if len(source)<4 else source\n        else:links.new(source,node.inputs[index])\n    return node.outputs['Color']\n\ndef _samplers(nodes,links,uv,images,metres_per_tile,label):\n    \"\"\"One mapping per texture set; every channel shares it so tiling is exact.\"\"\"\n    mapping=nodes.new('ShaderNodeMapping');mapping.vector_type='POINT'\n    mapping.inputs['Scale'].default_value=(1/metres_per_tile,)*3\n    links.new(uv,mapping.inputs['Vector'])\n    out={}\n    for channel,image in images.items():\n        sampler=nodes.new('ShaderNodeTexImage');sampler.image=image\n        sampler.label=f'{label} {channel} ({metres_per_tile:g} m per tile)'\n        links.new(mapping.outputs['Vector'],sampler.inputs['Vector'])\n        out[channel]=sampler.outputs['Color']\n    return out\n\ndef ground_material(bpy,c,guide='none',path_asset=PATH_TEXTURE,grass_asset=GRASS_TEXTURE,\n                    path_half_width=1.90,edge_width=.34,vertex_tint='terrain_shading'):\n    path=load_texture_set(bpy,path_asset);grass=load_texture_set(bpy,grass_asset)\n    mat=material(bpy,'Weathered courtyard path',(.36,.30,.22),roughness=.85)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    uv=nodes.new('ShaderNodeTexCoord').outputs['UV']\n    separate=nodes.new('ShaderNodeSeparateXYZ');links.new(uv,separate.inputs[0])\n    path_sources=_samplers(nodes,links,uv,path,.62,'path') if path else {}\n    grass_sources=_samplers(nodes,links,uv,grass,.42,'lawn') if grass else {}\n\n    # --- worn path / lawn boundary, broken up so the edge is never a straight line\n    boundary=nodes.new('ShaderNodeTexNoise');boundary.inputs['Scale'].default_value=2.6;boundary.inputs['Detail'].default_value=5\n    links.new(uv,boundary.inputs['Vector'])\n    wobble=nodes.new('ShaderNodeMath');wobble.operation='MULTIPLY';wobble.inputs[1].default_value=.42\n    links.new(boundary.outputs['Fac'],wobble.inputs[0])\n    absolute_y=nodes.new('ShaderNodeMath');absolute_y.operation='ABSOLUTE';links.new(separate.outputs['Y'],absolute_y.inputs[0])\n    shifted=nodes.new('ShaderNodeMath');shifted.operation='ADD'\n    links.new(absolute_y.outputs[0],shifted.inputs[0]);links.new(wobble.outputs[0],shifted.inputs[1])\n    is_lawn=nodes.new('ShaderNodeMapRange');is_lawn.interpolation_type='SMOOTHSTEP'\n    is_lawn.inputs['From Min'].default_value=path_half_width;is_lawn.inputs['From Max'].default_value=path_half_width+edge_width\n    links.new(shifted.outputs[0],is_lawn.inputs['Value'])\n    lawn=is_lawn.outputs['Result']\n\n    if path_sources:\n        # Damp/dry patches: one much coarser noise multiply kills the obvious repeat.\n        macro=nodes.new('ShaderNodeTexNoise');macro.inputs['Scale'].default_value=.38;macro.inputs['Detail'].default_value=4\n        stretch=nodes.new('ShaderNodeVectorMath');stretch.operation='MULTIPLY';stretch.inputs[1].default_value=(1.6,.85,1.)\n        links.new(uv,stretch.inputs[0]);links.new(stretch.outputs[0],macro.inputs['Vector'])\n        macro_ramp=nodes.new('ShaderNodeValToRGB')\n        macro_ramp.color_ramp.elements[0].position=.32;macro_ramp.color_ramp.elements[0].color=(.74,.68,.60,1)\n        macro_ramp.color_ramp.elements[1].position=.70;macro_ramp.color_ramp.elements[1].color=(1.08,1.04,.97,1)\n        links.new(macro.outputs['Fac'],macro_ramp.inputs[0])\n        path_colour=_mix(nodes,links,1.,path_sources['diff'],macro_ramp.outputs['Color'],'MULTIPLY')\n        path_rough=path_sources.get('rough',(.72,.72,.72))\n        path_height=path_sources.get('disp',(.5,.5,.5))\n        path_normal=path_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=5.;noise.inputs['Detail'].default_value=3\n        links.new(uv,noise.inputs['Vector'])\n        path_colour=_mix(nodes,links,noise.outputs['Fac'],(.175,.145,.105,1),(.31,.255,.185,1))\n        path_rough=path_height=path_normal=(.5,.5,.5);path_normal=(.5,.5,1.)\n\n    if grass_sources:\n        # The scanned lawn is dark olive; push it towards living turf so the path\n        # edge reads as earth-versus-grass instead of two similar browns.\n        grass_colour=_mix(nodes,links,1.,grass_sources['diff'],(1.0,1.16,.80),'MULTIPLY')\n        grass_rough=grass_sources.get('rough',(.80,.80,.80))\n        grass_height=grass_sources.get('disp',(.5,.5,.5))\n        grass_normal=grass_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=9.;noise.inputs['Detail'].default_value=6\n        links.new(uv,noise.inputs['Vector'])\n        grass_colour=_mix(nodes,links,noise.outputs['Fac'],(.045,.085,.028,1),(.135,.195,.055,1))\n        grass_rough=(.86,.86,.86);grass_height=(.5,.5,.5);grass_normal=(.5,.5,1.)\n\n    albedo=_mix(nodes,links,lawn,path_colour,grass_colour)\n    if path_sources.get('ao') or grass_sources.get('ao'):\n        occlusion=_mix(nodes,links,lawn,path_sources.get('ao',(1.,1.,1.)),grass_sources.get('ao',(1.,1.,1.)))\n        albedo=_mix(nodes,links,.75,albedo,occlusion,'MULTIPLY')\n    if vertex_tint:\n        tint=nodes.new('ShaderNodeVertexColor');tint.layer_name=vertex_tint\n        albedo=_mix(nodes,links,1.,albedo,tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n\n    span=nodes.new('ShaderNodeMapRange');span.inputs['To Min'].default_value=.58;span.inputs['To Max'].default_value=.97\n    links.new(_mix(nodes,links,lawn,path_rough,grass_rough),span.inputs['Value'])\n    links.new(span.outputs['Result'],shader.inputs['Roughness'])\n\n    # --- micro relief: mixed tangent-space normals, then the height map ------\n    normal_map=nodes.new('ShaderNodeNormalMap');normal_map.inputs['Strength'].default_value=.9;normal_map.space='TANGENT'\n    normal_map.uv_map='World metres'\n    links.new(_mix(nodes,links,lawn,path_normal,grass_normal),normal_map.inputs['Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.95;bump.inputs['Distance'].default_value=.02\n    links.new(_mix(nodes,links,lawn,path_height,grass_height),bump.inputs['Height'])\n    links.new(normal_map.outputs['Normal'],bump.inputs['Normal'])\n    links.new(bump.outputs['Normal'],shader.inputs['Normal'])\n\n    if guide=='contours':\n        position=nodes.new('ShaderNodeNewGeometry');xyz=nodes.new('ShaderNodeSeparateXYZ');links.new(position.outputs['Position'],xyz.inputs[0])\n        grade=nodes.new('ShaderNodeMath');grade.operation='MULTIPLY';grade.inputs[1].default_value=c['terrain_slope'];links.new(xyz.outputs['X'],grade.inputs[0])\n        subtract=nodes.new('ShaderNodeMath');subtract.operation='SUBTRACT';links.new(xyz.outputs['Z'],subtract.inputs[0]);links.new(grade.outputs[0],subtract.inputs[1])\n        baseline=nodes.new('ShaderNodeMath');baseline.operation='SUBTRACT';baseline.inputs[1].default_value=c['terrain_base_height'];links.new(subtract.outputs[0],baseline.inputs[0])\n        scale=nodes.new('ShaderNodeMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=50.;links.new(baseline.outputs[0],scale.inputs[0])\n        repeat=nodes.new('ShaderNodeMath');repeat.operation='PINGPONG';repeat.inputs[1].default_value=.5;links.new(scale.outputs[0],repeat.inputs[0])\n        threshold=nodes.new('ShaderNodeMath');threshold.operation='LESS_THAN';threshold.inputs[1].default_value=.016;links.new(repeat.outputs[0],threshold.inputs[0])\n        overlay=nodes.new('ShaderNodeMixRGB');overlay.blend_type='MIX'\n        links.new(albedo,overlay.inputs[1]);overlay.inputs[2].default_value=(.03,.09,.10,1)\n        links.new(threshold.outputs[0],overlay.inputs[0])\n        links.new(overlay.outputs['Color'],shader.inputs['Base Color'])\n    return mat\n\ndef bake_terrain_shading(mesh,vertices,c):\n    \"\"\"Bake cavity and slope into a colour attribute: shading data, not geometry.\n\n    Hollows collect damp fine material and read darker; exposed crests are\n    scuffed lighter. The tint is derived from the same height field the ball\n    collides with, so it cannot contradict the motion.\n    \"\"\"\n    import numpy as np\n    from scene_support.uneven_ground_ball.terrain_geometry import curvature\n    x=vertices[:,0];y=vertices[:,1]\n    lap=curvature(x,y,c)\n    # Positive Laplacian = hollow (surface curves up around the point).\n    cavity=np.clip(lap/6.,-1.,1.)\n    brightness=1.-.34*cavity\n    warm=np.clip(-cavity,0.,1.)\n    tint=np.stack((brightness+.05*warm,brightness,brightness-.06*warm),axis=1)\n    tint=np.clip(tint,0.,2.2)\n    attribute=mesh.color_attributes.new(name='terrain_shading',type='FLOAT_COLOR',domain='POINT')\n    rgba=np.concatenate((tint,np.ones((len(tint),1))),axis=1)\n    attribute.data.foreach_set('color',rgba.astype(np.float32).ravel())\n    return tint\n\ndef ball_material(bpy):\n    mat=material(bpy,'Orange and ivory rubber ball',(.74,.20,.035),roughness=.55)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');sep=nodes.new('ShaderNodeSeparateXYZ');links.new(coord.outputs['Generated'],sep.inputs[0])\n    centred=[]\n    for axis in ('X','Y'):\n        node=nodes.new('ShaderNodeMath');node.operation='SUBTRACT';node.inputs[1].default_value=.5;links.new(sep.outputs[axis],node.inputs[0]);centred.append(node)\n    angle=nodes.new('ShaderNodeMath');angle.operation='ARCTAN2';links.new(centred[1].outputs[0],angle.inputs[0]);links.new(centred[0].outputs[0],angle.inputs[1])\n    freq=nodes.new('ShaderNodeMath');freq.operation='MULTIPLY';freq.inputs[1].default_value=2;links.new(angle.outputs[0],freq.inputs[0])\n    wave=nodes.new('ShaderNodeMath');wave.operation='SINE';links.new(freq.outputs[0],wave.inputs[0]);split=nodes.new('ShaderNodeMath');split.operation='GREATER_THAN';links.new(wave.outputs[0],split.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB');mix.inputs[1].default_value=(.72,.16,.025,1);mix.inputs[2].default_value=(.87,.82,.66,1);links.new(split.outputs[0],mix.inputs[0]);links.new(mix.outputs[0],shader.inputs['Base Color'])\n    for name,value in (('Coat Weight',.25),('Coat Roughness',.28)):\n        if name in shader.inputs:shader.inputs[name].default_value=value\n    noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=220.;links.new(coord.outputs['Generated'],noise.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.14;bump.inputs['Distance'].default_value=.00018;links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef build_environment(bpy,c,path_half_width=1.90):\n    from scene_support.uneven_ground_ball.terrain_geometry import environment_boxes,height\n    timber=wood(bpy,'Oiled garden timber',(.31,.16,.065),(.095,.040,.016));pot=material(bpy,'Terracotta planter',(.43,.20,.095),roughness=.9)\n    for part in environment_boxes(c):box(bpy,part['name'],part['location'],part['size'],pot if part['kind']=='pot' else timber,bevel=.005)\n    soil=material(bpy,'Planter soil',(.08,.055,.025),roughness=1);leaves=material(bpy,'Garden herbs',(.10,.26,.075),roughness=.9)\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));box(bpy,'Soil in planter',[x,2.55,z+.322],[.34,.32,.012],soil)\n        for i in range(7):\n            angle=2*math.pi*i/7\n            bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=1,location=[x+.10*math.cos(angle),2.55+.08*math.sin(angle),z+.40+.04*(i%2)])\n            leaf=bpy.context.object;leaf.name='Herb cluster';leaf.scale=(.09,.07,.14);leaf.data.materials.append(leaves)\n            for face in leaf.data.polygons:face.use_smooth=True\n    # Fine grass blades are decorative vegetation, kept clear of the rolling path.\n    rng=random.Random(418);vertices=[];faces=[]\n    for _ in range(2600):\n        x=rng.uniform(-3.4,6.6);y=rng.choice((-1,1))*rng.uniform(path_half_width+.22,3.05);z=float(height(x,y,c))\n        angle=rng.uniform(0,2*math.pi);width=rng.uniform(.003,.006);length=rng.uniform(.014,.040)\n        dx=width*math.cos(angle);dy=width*math.sin(angle);start=len(vertices)\n        vertices.extend([(x-dx,y-dy,z),(x+dx,y+dy,z),(x+.006*math.cos(angle+.7),y+.006*math.sin(angle+.7),z+length)])\n        faces.append((start,start+1,start+2))\n    mesh=bpy.data.meshes.new('Garden grass blades');mesh.from_pydata(vertices,[],faces);mesh.update()\n    grass=bpy.data.objects.new('Grass around path',mesh);bpy.context.scene.collection.objects.link(grass);grass.data.materials.append(material(bpy,'Grass blades',(.085,.175,.038),roughness=.9))\n\ndef stone_material(bpy):\n    mat=material(bpy,'Path grit and small stones',(.30,.27,.22),roughness=.82)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=180.;noise.inputs['Detail'].default_value=8\n    links.new(coord.outputs['Object'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position=.28;ramp.color_ramp.elements[0].color=(.085,.078,.064,1)\n    ramp.color_ramp.elements[1].position=.74;ramp.color_ramp.elements[1].color=(.52,.48,.41,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    tint=nodes.new('ShaderNodeVertexColor');tint.layer_name='stone_tint'\n    albedo=_mix(nodes,links,1.,ramp.outputs['Color'],tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.55;bump.inputs['Distance'].default_value=.003\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef _unit_stone(rings=4,segments=7):\n    \"\"\"Angular, cheap, and irregular once squashed: reads as grit, not a ball.\"\"\"\n    vertices=[(0.,0.,1.)];faces=[]\n    for ring in range(1,rings):\n        phi=math.pi*ring/rings;radius=math.sin(phi);z=math.cos(phi)\n        for segment in range(segments):\n            theta=2*math.pi*segment/segments\n            vertices.append((radius*math.cos(theta),radius*math.sin(theta),z))\n    vertices.append((0.,0.,-1.));south=len(vertices)-1\n    for segment in range(segments):\n        faces.append((0,1+segment,1+(segment+1)%segments))\n    for ring in range(rings-2):\n        for segment in range(segments):\n            a=1+ring*segments+segment;b=1+ring*segments+(segment+1)%segments\n            faces.extend([(a,b,b+segments),(a,b+segments,a+segments)])\n    base=1+(rings-2)*segments\n    for segment in range(segments):\n        faces.append((south,base+(segment+1)%segments,base+segment))\n    return vertices,faces\n\ndef scatter_gravel(bpy,c,frames,path_half_width=1.90,count=520,seed=517):\n    \"\"\"Loose grit and small stones lying on the path.\n\n    Decorative only: every stone is rejected if it lands inside the corridor the\n    ball sweeps, so the visible surface never contradicts the simulated contact\n    geometry. Placement is seeded, so a rerun reproduces the same stones.\n    \"\"\"\n    from scene_support.uneven_ground_ball.terrain_geometry import height\n    rng=random.Random(seed)\n    template,template_faces=_unit_stone()\n    trajectory=[(frame['ball']['location'][0],frame['ball']['location'][1]) for frame in frames]\n    clearance=c['ball_radius']+.09\n    vertices=[];faces=[];tints=[];placed=0\n    for _ in range(count*4):\n        if placed>=count:break\n        x=rng.uniform(-3.6,3.1);y=rng.uniform(-2.1,2.1)\n        if min(math.hypot(x-tx,y-ty) for tx,ty in trajectory)<clearance:continue\n        z=float(height(x,y,c))\n        roll=rng.random()\n        size=rng.uniform(.009,.026) if roll<.90 else rng.uniform(.030,.058)\n        squash=rng.uniform(.40,.60);spin=rng.uniform(0,2*math.pi);tilt=rng.uniform(-.40,.40)\n        ca,sa,ct,st=math.cos(spin),math.sin(spin),math.cos(tilt),math.sin(tilt)\n        shade=rng.uniform(.48,1.12);warmth=rng.uniform(.92,1.12)\n        tint=(shade*warmth,shade,shade/warmth,1.)\n        base_vertices=len(vertices)\n        for vx,vy,vz in template:\n            # tilt, then spin, then squash, then settle into the ground\n            ty,tz=vy*ct-vz*st,vy*st+vz*ct\n            fx,fy=vx*ca-ty*sa,vx*sa+ty*ca\n            vertices.append((x+fx*size,y+fy*size,z+tz*size*squash-size*squash*.42))\n            tints.append(tint)\n        for corner in template_faces:\n            faces.append(tuple(base_vertices+index for index in corner))\n        placed+=1\n    mesh=bpy.data.meshes.new('Loose grit');mesh.from_pydata(vertices,[],faces);mesh.update()\n    attribute=mesh.color_attributes.new(name='stone_tint',type='FLOAT_COLOR',domain='POINT')\n    attribute.data.foreach_set('color',__import__('numpy').asarray(tints,dtype='float32').ravel())\n    stones=bpy.data.objects.new('Loose grit on path',mesh);bpy.context.scene.collection.objects.link(stones)\n    stones.data.materials.append(stone_material(bpy))\n    return placed\n\ndef build_lighting(bpy,scene):\n    \"\"\"One low raking sun for relief, plus sky and soft bounce fills.\n\n    A diffuse dome from above renders a rutted path as flat colour; the whole\n    point here is that a low sun throws a shadow across every crest.\n    \"\"\"\n    sun_target=(.85,-.25,.10);sun_from=(5.00,.05,.95)\n    bpy.ops.object.light_add(type='SUN');sun=bpy.context.object;sun.name='Low raking sun'\n    sun.data.energy=5.0;sun.data.angle=.018;sun.data.color=(1.,.83,.63);sun.data.use_shadow=True\n    if hasattr(sun.data,'shadow_maximum_resolution'):sun.data.shadow_maximum_resolution=.0002\n    sun.rotation_euler=_aim(sun_target,sun_from)\n    for name,location,power,size,color in [('Sky bounce',[-1.9,-3.2,2.6],13,4.5,(.66,.78,1.)),\n                                           ('Warm bounce',[.6,2.6,1.1],6,3.2,(1.,.86,.70))]:\n        bpy.ops.object.light_add(type='AREA',location=location);light=bpy.context.object;light.name=name\n        light.data.energy=power;light.data.shape='DISK';light.data.size=size;light.data.color=color;light.data.use_shadow=True\n        light.rotation_euler=_aim((.7,.4,.12),location)\n    return sun\n\ndef _aim(target,source):\n    from mathutils import Vector\n    return (Vector(target)-Vector(source)).to_track_quat('-Z','Y').to_euler()\n", "scene_support.uneven_ground_ball.terrain_geometry": "\"\"\"A continuous terrain mesh shared by collision, rendering and diagnostics.\n\nThe height field is the single source of truth: the collision mesh handed to\npybullet, the render mesh and the ground-truth archive are all built from it, so\nwhat the camera sees is exactly what the ball touches.\n\nRelief is layered on purpose:\n  * a global grade along +x (the path falls away as the ball travels),\n  * named features (wheel ruts, a crown between them, mounds, a pothole) whose\n    footprint is several times the 5 cm mesh spacing, so the mesh represents\n    them faithfully,\n  * a fractal octave stack for the irregular small undulation of packed earth.\n\nAnything finer than roughly two mesh cells cannot be represented by vertices and\nis deliberately left to the material's normal/displacement maps, which change\nshading only and never move the collision surface.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport numpy as np\nimport hashlib\n\n# wavelength (m), amplitude (m), azimuth (deg), phase (rad).\n# The ratios are deliberately irrational so the sum does not read as corrugation.\n# Most of the energy sits between 0.2 m and 1 m: that is the band a 0.10 m ball\n# actually feels and the band a camera at 3 m actually sees.\nOCTAVES=((2.30,.0210,12,.31),(1.35,.0200,64,2.05),(.86,.0240,29,4.13),\n         (.55,.0170,101,1.62),(.34,.0110,47,5.07),(.21,.0062,139,3.41))\n\ndef _fractal(x,y,roughness):\n    \"\"\"Domain-warped octave stack: irregular, deterministic, no RNG.\"\"\"\n    z=np.zeros_like(np.asarray(x,dtype=float))\n    for wavelength,amplitude,azimuth,phase in OCTAVES:\n        k=2*np.pi/wavelength;theta=np.radians(azimuth);kx,ky=k*np.cos(theta),k*np.sin(theta)\n        warp=np.sin(.61*kx*x-1.27*ky*y+.87)\n        z=z+amplitude*np.sin(kx*x+ky*y+phase+warp)\n    return roughness*z\n\ndef height(x,y,c):\n    x=np.asarray(x,dtype=float);y=np.asarray(y,dtype=float)\n    z=c['terrain_base_height']+c['terrain_slope']*x\n    for cx,cy,amplitude,sx,sy in c['bumps']:\n        z=z+amplitude*np.exp(-.5*(((x-cx)/sx)**2+((y-cy)/sy)**2))\n    return z+_fractal(x,y,c['terrain_roughness'])\n\ndef normal(x,y,c):\n    eps=1e-4;dx=(height(x+eps,y,c)-height(x-eps,y,c))/(2*eps);dy=(height(x,y+eps,c)-height(x,y-eps,c))/(2*eps)\n    n=np.array([-float(dx),-float(dy),1.]);return n/np.linalg.norm(n)\n\ndef curvature(x,y,c,h=.05):\n    \"\"\"Laplacian of the height field: negative in hollows, positive on crests.\n\n    Used by the ground material to settle dust into dips and wear the crests,\n    which is what makes relief readable long before lighting does.\n    \"\"\"\n    lap=height(x+h,y,c)+height(x-h,y,c)+height(x,y+h,c)+height(x,y-h,c)-4*height(x,y,c)\n    return lap/(h*h)\n\ndef terrain_mesh(c):\n    lo,hi=c['terrain_bounds'];nx,ny=c['terrain_cells'];xs=np.linspace(lo[0],hi[0],nx+1);ys=np.linspace(lo[1],hi[1],ny+1)\n    x,y=np.meshgrid(xs,ys,indexing='ij');v=np.column_stack((x.ravel(),y.ravel(),height(x,y,c).ravel()))\n    faces=[]\n    for i in range(nx):\n        for j in range(ny):\n            a=i*(ny+1)+j;b=a+ny+1\n            faces.extend([(a,b,b+1),(a,b+1,a+1)])\n    f=np.asarray(faces,dtype=np.int32)\n    return v,f\n\ndef mesh_hash(v,f):return hashlib.sha256(np.asarray(v,dtype=np.float64).tobytes()+np.asarray(f,dtype=np.int32).tobytes()).hexdigest()\n\ndef initial_state(c):\n    x,y=c['ball_start_xy'];n=normal(x,y,c);pos=np.array([x,y,float(height(x,y,c))])+(c['ball_radius']+.0015)*n\n    direction=np.array([1.,0,0]);direction-=np.dot(direction,n)*n;direction/=np.linalg.norm(direction)\n    velocity=c['ball_speed']*direction;omega=np.cross(n,velocity)/c['ball_radius']\n    return pos,velocity,omega\n\ndef environment_boxes(c):\n    parts=[]\n    def add(name,location,size,kind):parts.append(dict(name=name,location=location,size=size,kind=kind))\n    h=float(height(.3,2.62,c))\n    add('Garden bench seat',[.3,2.62,h+.44],[1.4,.42,.07],'wood')\n    add('Garden bench back',[.3,2.81,h+.70],[1.4,.05,.30],'wood')\n    for x in (-.24,.84):\n        for y in (2.48,2.76):\n            foot=float(height(x,y,c));length=h+.405-foot\n            add('Bench leg',[x,y,foot+length/2],[.055,.055,length],'wood')\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));add('Terracotta planter',[x,2.55,z+.16],[.38,.36,.32],'pot')\n    for x in np.linspace(-2.8,6.6,40):\n        z=float(height(x,3.1,c));add('Garden fence slat',[float(x),3.1,z+.40],[.15,.035,.80],'wood')\n    return parts\n", "scene_support.uneven_ground_ball.video_presentation": "\"\"\"Clearly label display-only terrain guides without modifying simulated geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport shutil\nimport numpy as np\nfrom PIL import Image,ImageDraw,ImageFont\nimport imageio.v2 as imageio\n\ndef caption(pixels,gt,index):\n    picture=Image.fromarray(pixels).convert('RGBA');overlay=Image.new('RGBA',picture.size)\n    draw=ImageDraw.Draw(overlay);width,height=picture.size;size=max(12,round(17*width/960))\n    try:font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',size)\n    except OSError:font=ImageFont.load_default()\n    guide=gt['scenario']['render'].get('surface_guide','none')\n    view=gt['scenario']['render'].get('view','terrain')\n    text='2 cm relief contours | display guide; geometry unchanged' if guide=='contours' else 'Low raking sunlight | ground = simulated collision mesh'\n    bar_height=max(30,round(36*width/960));draw.rectangle((0,0,width,bar_height),fill=(18,25,28,205))\n    draw.text((14,8),text,font=font,fill=(245,235,211,255))\n    time=gt['frames'][index]['time_sec'];slow=gt['slow_motion'];speed='real speed' if slow==1 else f'{slow}x slow'\n    right=f't={time:.2f}s | {speed}';draw.text((width-draw.textbbox((0,0),right,font=font)[2]-14,8),right,font=font,fill=(236,196,124,255))\n    return np.asarray(Image.alpha_composite(picture,overlay).convert('RGB'))\n\ndef label_outputs(out,gt,preview_frame,animation=False):\n    out=Path(out);raw=out/'preview_unlabelled.png';shutil.copy2(out/'preview.png',raw)\n    with Image.open(raw) as picture:Image.fromarray(caption(np.asarray(picture.convert('RGB')),gt,preview_frame-1)).save(out/'preview.png')\n    if animation:\n        reader=imageio.get_reader(out/'uneven_ground_ball.mp4')\n        try:\n            with imageio.get_writer(out/'video.mp4',fps=gt['fps'],codec='libx264',quality=8,macro_block_size=1) as writer:\n                for i,pixels in enumerate(reader):writer.append_data(caption(pixels,gt,i))\n        finally:reader.close()\n", "scene_support.uneven_ground_ball": "\"\"\"Shared support modules for uneven_ground_ball.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os,sys\nfrom pathlib import Path\n\nROOT=_PCVE_ROOT\n_dll_handles=[]\nif os.name=='nt':\n    directory=Path(sys.prefix)/'Library/bin'\n    if directory.exists():_dll_handles.append(os.add_dll_directory(str(directory)))\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_config": "\"\"\"A ball rolling over a rutted, sloping earth path. SI units.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport math\n\nSCENE_NAME='uneven_ground_ball'\nTOTAL_FRAMES=72\n# Low, near-grazing three-quarter view: the horizon line sits close to the ball,\n# so every crest and hollow of the path breaks the silhouette instead of being\n# flattened into a top-down texture.\nTERRAIN_CAMERA=dict(location=[-0.50,-2.20,.66],target=[-0.50,-.10,.10],lens_mm=26)\nBASELINE_PHYSICS=dict(gravity=[0,0,-9.81],ball_radius=.10,ball_mass=.45,ball_speed=1.4,ball_inertia_factor=.64,\n    ball_start_xy=[-1.8,-.20],ball_friction=.35,ball_rolling_friction=.0015,\n    ball_restitution=.05,ground_friction=1.,substeps=40,solver_iterations=100,\n    terrain_bounds=[[-8.,-8.],[12.,8.]],terrain_cells=[400,320],\n    terrain_base_height=.08,terrain_slope=-.016,terrain_roughness=1.,    # cx, cy, amplitude, sigma_x, sigma_y. Negative amplitude is a hollow.\n    # A broad worn trough carries the ball along +x; discrete mounds and hollows\n    # inside and beside it make the path wander without throwing the ball off it.\n    bumps=[[-.30,-.30,-.040,2.40,.50],\n           [.90,-.50,-.045,.340,.300],\n           [.60,.25,.045,.400,.300],\n           [-1.20,-.45,-.040,.300,.280],\n           [1.80,-.20,.040,.400,.340]])\n\ndef defaults():\n    return dict(schema_version=1,scene=SCENE_NAME,physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24,duration_sec=3.,slow_motion=1,resolution=[960,540],samples=16),\n        camera=dict(location=[-0.55,-2.95,3.6],target=[.75,-.15,.1],lens_mm=35))\n\ndef merge(base,overrides):\n    result=deepcopy(base)\n    for key,value in overrides.items():result[key]=merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\ndef validate(s):\n    if set(s)-{'schema_version','scene','physics','render','camera','seed'}:raise ValueError('Unknown scenario field; nest physics overrides under physics')\n    c=s['physics'];r=s['render']\n    if set(c)-set(BASELINE_PHYSICS):raise ValueError('Unknown physics parameter')\n    for key in ('ball_radius','ball_mass','ball_inertia_factor','ground_friction','substeps','solver_iterations'):\n        if not math.isfinite(c[key]) or c[key]<=0:raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_speed','ball_friction','ball_rolling_friction','terrain_roughness'):\n        if not math.isfinite(c[key]) or c[key]<0:raise ValueError(f'{key} must be nonnegative and finite')\n    if not 0<=c['ball_restitution']<=1:raise ValueError('Invalid restitution')\n    if len(c['gravity'])!=3 or not all(math.isfinite(v) for v in c['gravity']):raise ValueError('Invalid gravity')\n    lo,hi=c['terrain_bounds']\n    if len(lo)!=2 or len(hi)!=2 or any(not math.isfinite(v) for v in lo+hi) or any(a>=b for a,b in zip(lo,hi)):raise ValueError('Invalid ground bounds')\n    if len(c['terrain_cells'])!=2 or any(n<2 or n!=int(n) for n in c['terrain_cells']):raise ValueError('Invalid terrain discretization')\n    if len(c['ball_start_xy'])!=2 or any(not a+c['ball_radius']<v<b-c['ball_radius'] for a,b,v in zip(lo,hi,c['ball_start_xy'])):raise ValueError('Ball starts outside terrain')\n    for bump in c['bumps']:\n        if len(bump)!=5 or not all(math.isfinite(v) for v in bump) or min(bump[3:])<=0:raise ValueError('Invalid terrain bump')\n    if r['fps']<=0 or r['duration_sec']<=0 or r['slow_motion'] not in (1,2,4,8) or c['substeps']%r['slow_motion']:raise ValueError('Invalid sampling or slow motion')\n", "scene_environment": "\"\"\"Courtyard environment and physically based ground shading.\n\nThe ground is the simulation mesh itself: nothing here moves a vertex. Real\nmaterial response (albedo, roughness, normal, ambient occlusion) comes from CC0\nPoly Haven texture sets, which supply exactly the sub-centimetre relief the 5 cm\ncollision grid cannot carry. When a texture set is missing the material degrades\nto the earlier procedural look instead of failing.\n\nThree physics-neutral cues make the undulation read:\n  1. a low raking sun, so every crest throws a shadow into the trough beside it,\n  2. baked cavity/slope tint from the height field itself (dust settles in\n     hollows, crests are scuffed bare),\n  3. normal and displacement maps at sub-mesh scale.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport json,math,random\n\nHERE=_PCVE_ROOT/'assets'/'polyhaven'/'uneven_ground_ball'\n# Same location and naming as the other scenes in /scripts: <asset>_<channel>_<res>.jpg\nASSETS=HERE\nPATH_TEXTURE='floor_pebbles_01'\nGRASS_TEXTURE='grass_ground'\nRESOLUTION='2k'\nCHANNELS=('diff','disp','nor_gl','rough','ao')\n\ndef material(bpy,name,color,metal=0,roughness=.5):\n    mat=bpy.data.materials.new(name);mat.diffuse_color=(*color,1);mat.use_nodes=True\n    shader=mat.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Base Color'].default_value=(*color,1);shader.inputs['Metallic'].default_value=metal;shader.inputs['Roughness'].default_value=roughness\n    return mat\n\ndef wood(bpy,name,light=(.40,.24,.115),dark=(.20,.095,.038)):\n    mat=material(bpy,name,light,roughness=.48);nodes=mat.node_tree.nodes;links=mat.node_tree.links\n    coords=nodes.new('ShaderNodeTexCoord');scale=nodes.new('ShaderNodeVectorMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=(2,95,5)\n    links.new(coords.outputs['Generated'],scale.inputs[0]);noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=2.5;noise.inputs['Detail'].default_value=3\n    links.new(scale.outputs[0],noise.inputs['Vector']);ramp=nodes.new('ShaderNodeValToRGB');ramp.color_ramp.elements[0].color=(*dark,1);ramp.color_ramp.elements[1].color=(*light,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0]);shader=nodes.get('Principled BSDF');links.new(ramp.outputs['Color'],shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.16;bump.inputs['Distance'].default_value=.0007\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal']);return mat\n\ndef box(bpy,name,location,size,mat,pitch=0,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=location);obj=bpy.context.object;obj.name=name;obj.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True);obj.rotation_euler[1]=pitch;obj.data.materials.append(mat)\n    if bevel:\n        mod=obj.modifiers.new('Manufactured edge','BEVEL');mod.width=bevel;mod.segments=3;obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef load_texture_set(bpy,asset,resolution=RESOLUTION):\n    \"\"\"Return {channel: bpy.types.Image} for a fetched Poly Haven set, or {}.\"\"\"\n    images={}\n    for channel in CHANNELS:\n        path=ASSETS/f'{asset}_{channel}_{resolution}.jpg'\n        if not path.exists():continue\n        image=bpy.data.images.load(str(path),check_existing=True)\n        image.colorspace_settings.name='sRGB' if channel=='diff' else 'Non-Color'\n        images[channel]=image\n    return images\n\ndef _mix(nodes,links,factor,first,second,blend='MIX'):\n    \"\"\"MixRGB that accepts either a socket, an RGB tuple, or a numeric factor.\"\"\"\n    node=nodes.new('ShaderNodeMixRGB');node.blend_type=blend\n    if isinstance(factor,(int,float)):node.inputs[0].default_value=factor\n    else:links.new(factor,node.inputs[0])\n    for source,index in ((first,1),(second,2)):\n        if isinstance(source,tuple):\n            node.inputs[index].default_value=tuple(source)+(1.,)*(4-len(source)) if len(source)<4 else source\n        else:links.new(source,node.inputs[index])\n    return node.outputs['Color']\n\ndef _samplers(nodes,links,uv,images,metres_per_tile,label):\n    \"\"\"One mapping per texture set; every channel shares it so tiling is exact.\"\"\"\n    mapping=nodes.new('ShaderNodeMapping');mapping.vector_type='POINT'\n    mapping.inputs['Scale'].default_value=(1/metres_per_tile,)*3\n    links.new(uv,mapping.inputs['Vector'])\n    out={}\n    for channel,image in images.items():\n        sampler=nodes.new('ShaderNodeTexImage');sampler.image=image\n        sampler.label=f'{label} {channel} ({metres_per_tile:g} m per tile)'\n        links.new(mapping.outputs['Vector'],sampler.inputs['Vector'])\n        out[channel]=sampler.outputs['Color']\n    return out\n\ndef ground_material(bpy,c,guide='none',path_asset=PATH_TEXTURE,grass_asset=GRASS_TEXTURE,\n                    path_half_width=1.90,edge_width=.34,vertex_tint='terrain_shading'):\n    path=load_texture_set(bpy,path_asset);grass=load_texture_set(bpy,grass_asset)\n    mat=material(bpy,'Weathered courtyard path',(.36,.30,.22),roughness=.85)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    uv=nodes.new('ShaderNodeTexCoord').outputs['UV']\n    separate=nodes.new('ShaderNodeSeparateXYZ');links.new(uv,separate.inputs[0])\n    path_sources=_samplers(nodes,links,uv,path,.62,'path') if path else {}\n    grass_sources=_samplers(nodes,links,uv,grass,.42,'lawn') if grass else {}\n\n    # --- worn path / lawn boundary, broken up so the edge is never a straight line\n    boundary=nodes.new('ShaderNodeTexNoise');boundary.inputs['Scale'].default_value=2.6;boundary.inputs['Detail'].default_value=5\n    links.new(uv,boundary.inputs['Vector'])\n    wobble=nodes.new('ShaderNodeMath');wobble.operation='MULTIPLY';wobble.inputs[1].default_value=.42\n    links.new(boundary.outputs['Fac'],wobble.inputs[0])\n    absolute_y=nodes.new('ShaderNodeMath');absolute_y.operation='ABSOLUTE';links.new(separate.outputs['Y'],absolute_y.inputs[0])\n    shifted=nodes.new('ShaderNodeMath');shifted.operation='ADD'\n    links.new(absolute_y.outputs[0],shifted.inputs[0]);links.new(wobble.outputs[0],shifted.inputs[1])\n    is_lawn=nodes.new('ShaderNodeMapRange');is_lawn.interpolation_type='SMOOTHSTEP'\n    is_lawn.inputs['From Min'].default_value=path_half_width;is_lawn.inputs['From Max'].default_value=path_half_width+edge_width\n    links.new(shifted.outputs[0],is_lawn.inputs['Value'])\n    lawn=is_lawn.outputs['Result']\n\n    if path_sources:\n        # Damp/dry patches: one much coarser noise multiply kills the obvious repeat.\n        macro=nodes.new('ShaderNodeTexNoise');macro.inputs['Scale'].default_value=.38;macro.inputs['Detail'].default_value=4\n        stretch=nodes.new('ShaderNodeVectorMath');stretch.operation='MULTIPLY';stretch.inputs[1].default_value=(1.6,.85,1.)\n        links.new(uv,stretch.inputs[0]);links.new(stretch.outputs[0],macro.inputs['Vector'])\n        macro_ramp=nodes.new('ShaderNodeValToRGB')\n        macro_ramp.color_ramp.elements[0].position=.32;macro_ramp.color_ramp.elements[0].color=(.74,.68,.60,1)\n        macro_ramp.color_ramp.elements[1].position=.70;macro_ramp.color_ramp.elements[1].color=(1.08,1.04,.97,1)\n        links.new(macro.outputs['Fac'],macro_ramp.inputs[0])\n        path_colour=_mix(nodes,links,1.,path_sources['diff'],macro_ramp.outputs['Color'],'MULTIPLY')\n        path_rough=path_sources.get('rough',(.72,.72,.72))\n        path_height=path_sources.get('disp',(.5,.5,.5))\n        path_normal=path_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=5.;noise.inputs['Detail'].default_value=3\n        links.new(uv,noise.inputs['Vector'])\n        path_colour=_mix(nodes,links,noise.outputs['Fac'],(.175,.145,.105,1),(.31,.255,.185,1))\n        path_rough=path_height=path_normal=(.5,.5,.5);path_normal=(.5,.5,1.)\n\n    if grass_sources:\n        # The scanned lawn is dark olive; push it towards living turf so the path\n        # edge reads as earth-versus-grass instead of two similar browns.\n        grass_colour=_mix(nodes,links,1.,grass_sources['diff'],(1.0,1.16,.80),'MULTIPLY')\n        grass_rough=grass_sources.get('rough',(.80,.80,.80))\n        grass_height=grass_sources.get('disp',(.5,.5,.5))\n        grass_normal=grass_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=9.;noise.inputs['Detail'].default_value=6\n        links.new(uv,noise.inputs['Vector'])\n        grass_colour=_mix(nodes,links,noise.outputs['Fac'],(.045,.085,.028,1),(.135,.195,.055,1))\n        grass_rough=(.86,.86,.86);grass_height=(.5,.5,.5);grass_normal=(.5,.5,1.)\n\n    albedo=_mix(nodes,links,lawn,path_colour,grass_colour)\n    if path_sources.get('ao') or grass_sources.get('ao'):\n        occlusion=_mix(nodes,links,lawn,path_sources.get('ao',(1.,1.,1.)),grass_sources.get('ao',(1.,1.,1.)))\n        albedo=_mix(nodes,links,.75,albedo,occlusion,'MULTIPLY')\n    if vertex_tint:\n        tint=nodes.new('ShaderNodeVertexColor');tint.layer_name=vertex_tint\n        albedo=_mix(nodes,links,1.,albedo,tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n\n    span=nodes.new('ShaderNodeMapRange');span.inputs['To Min'].default_value=.58;span.inputs['To Max'].default_value=.97\n    links.new(_mix(nodes,links,lawn,path_rough,grass_rough),span.inputs['Value'])\n    links.new(span.outputs['Result'],shader.inputs['Roughness'])\n\n    # --- micro relief: mixed tangent-space normals, then the height map ------\n    normal_map=nodes.new('ShaderNodeNormalMap');normal_map.inputs['Strength'].default_value=.9;normal_map.space='TANGENT'\n    normal_map.uv_map='World metres'\n    links.new(_mix(nodes,links,lawn,path_normal,grass_normal),normal_map.inputs['Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.95;bump.inputs['Distance'].default_value=.02\n    links.new(_mix(nodes,links,lawn,path_height,grass_height),bump.inputs['Height'])\n    links.new(normal_map.outputs['Normal'],bump.inputs['Normal'])\n    links.new(bump.outputs['Normal'],shader.inputs['Normal'])\n\n    if guide=='contours':\n        position=nodes.new('ShaderNodeNewGeometry');xyz=nodes.new('ShaderNodeSeparateXYZ');links.new(position.outputs['Position'],xyz.inputs[0])\n        grade=nodes.new('ShaderNodeMath');grade.operation='MULTIPLY';grade.inputs[1].default_value=c['terrain_slope'];links.new(xyz.outputs['X'],grade.inputs[0])\n        subtract=nodes.new('ShaderNodeMath');subtract.operation='SUBTRACT';links.new(xyz.outputs['Z'],subtract.inputs[0]);links.new(grade.outputs[0],subtract.inputs[1])\n        baseline=nodes.new('ShaderNodeMath');baseline.operation='SUBTRACT';baseline.inputs[1].default_value=c['terrain_base_height'];links.new(subtract.outputs[0],baseline.inputs[0])\n        scale=nodes.new('ShaderNodeMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=50.;links.new(baseline.outputs[0],scale.inputs[0])\n        repeat=nodes.new('ShaderNodeMath');repeat.operation='PINGPONG';repeat.inputs[1].default_value=.5;links.new(scale.outputs[0],repeat.inputs[0])\n        threshold=nodes.new('ShaderNodeMath');threshold.operation='LESS_THAN';threshold.inputs[1].default_value=.016;links.new(repeat.outputs[0],threshold.inputs[0])\n        overlay=nodes.new('ShaderNodeMixRGB');overlay.blend_type='MIX'\n        links.new(albedo,overlay.inputs[1]);overlay.inputs[2].default_value=(.03,.09,.10,1)\n        links.new(threshold.outputs[0],overlay.inputs[0])\n        links.new(overlay.outputs['Color'],shader.inputs['Base Color'])\n    return mat\n\ndef bake_terrain_shading(mesh,vertices,c):\n    \"\"\"Bake cavity and slope into a colour attribute: shading data, not geometry.\n\n    Hollows collect damp fine material and read darker; exposed crests are\n    scuffed lighter. The tint is derived from the same height field the ball\n    collides with, so it cannot contradict the motion.\n    \"\"\"\n    import numpy as np\n    from scene_support.uneven_ground_ball.terrain_geometry import curvature\n    x=vertices[:,0];y=vertices[:,1]\n    lap=curvature(x,y,c)\n    # Positive Laplacian = hollow (surface curves up around the point).\n    cavity=np.clip(lap/6.,-1.,1.)\n    brightness=1.-.34*cavity\n    warm=np.clip(-cavity,0.,1.)\n    tint=np.stack((brightness+.05*warm,brightness,brightness-.06*warm),axis=1)\n    tint=np.clip(tint,0.,2.2)\n    attribute=mesh.color_attributes.new(name='terrain_shading',type='FLOAT_COLOR',domain='POINT')\n    rgba=np.concatenate((tint,np.ones((len(tint),1))),axis=1)\n    attribute.data.foreach_set('color',rgba.astype(np.float32).ravel())\n    return tint\n\ndef ball_material(bpy):\n    mat=material(bpy,'Orange and ivory rubber ball',(.74,.20,.035),roughness=.55)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');sep=nodes.new('ShaderNodeSeparateXYZ');links.new(coord.outputs['Generated'],sep.inputs[0])\n    centred=[]\n    for axis in ('X','Y'):\n        node=nodes.new('ShaderNodeMath');node.operation='SUBTRACT';node.inputs[1].default_value=.5;links.new(sep.outputs[axis],node.inputs[0]);centred.append(node)\n    angle=nodes.new('ShaderNodeMath');angle.operation='ARCTAN2';links.new(centred[1].outputs[0],angle.inputs[0]);links.new(centred[0].outputs[0],angle.inputs[1])\n    freq=nodes.new('ShaderNodeMath');freq.operation='MULTIPLY';freq.inputs[1].default_value=2;links.new(angle.outputs[0],freq.inputs[0])\n    wave=nodes.new('ShaderNodeMath');wave.operation='SINE';links.new(freq.outputs[0],wave.inputs[0]);split=nodes.new('ShaderNodeMath');split.operation='GREATER_THAN';links.new(wave.outputs[0],split.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB');mix.inputs[1].default_value=(.72,.16,.025,1);mix.inputs[2].default_value=(.87,.82,.66,1);links.new(split.outputs[0],mix.inputs[0]);links.new(mix.outputs[0],shader.inputs['Base Color'])\n    for name,value in (('Coat Weight',.25),('Coat Roughness',.28)):\n        if name in shader.inputs:shader.inputs[name].default_value=value\n    noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=220.;links.new(coord.outputs['Generated'],noise.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.14;bump.inputs['Distance'].default_value=.00018;links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef build_environment(bpy,c,path_half_width=1.90):\n    from scene_support.uneven_ground_ball.terrain_geometry import environment_boxes,height\n    timber=wood(bpy,'Oiled garden timber',(.31,.16,.065),(.095,.040,.016));pot=material(bpy,'Terracotta planter',(.43,.20,.095),roughness=.9)\n    for part in environment_boxes(c):box(bpy,part['name'],part['location'],part['size'],pot if part['kind']=='pot' else timber,bevel=.005)\n    soil=material(bpy,'Planter soil',(.08,.055,.025),roughness=1);leaves=material(bpy,'Garden herbs',(.10,.26,.075),roughness=.9)\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));box(bpy,'Soil in planter',[x,2.55,z+.322],[.34,.32,.012],soil)\n        for i in range(7):\n            angle=2*math.pi*i/7\n            bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=1,location=[x+.10*math.cos(angle),2.55+.08*math.sin(angle),z+.40+.04*(i%2)])\n            leaf=bpy.context.object;leaf.name='Herb cluster';leaf.scale=(.09,.07,.14);leaf.data.materials.append(leaves)\n            for face in leaf.data.polygons:face.use_smooth=True\n    # Fine grass blades are decorative vegetation, kept clear of the rolling path.\n    rng=random.Random(418);vertices=[];faces=[]\n    for _ in range(2600):\n        x=rng.uniform(-3.4,6.6);y=rng.choice((-1,1))*rng.uniform(path_half_width+.22,3.05);z=float(height(x,y,c))\n        angle=rng.uniform(0,2*math.pi);width=rng.uniform(.003,.006);length=rng.uniform(.014,.040)\n        dx=width*math.cos(angle);dy=width*math.sin(angle);start=len(vertices)\n        vertices.extend([(x-dx,y-dy,z),(x+dx,y+dy,z),(x+.006*math.cos(angle+.7),y+.006*math.sin(angle+.7),z+length)])\n        faces.append((start,start+1,start+2))\n    mesh=bpy.data.meshes.new('Garden grass blades');mesh.from_pydata(vertices,[],faces);mesh.update()\n    grass=bpy.data.objects.new('Grass around path',mesh);bpy.context.scene.collection.objects.link(grass);grass.data.materials.append(material(bpy,'Grass blades',(.085,.175,.038),roughness=.9))\n\ndef stone_material(bpy):\n    mat=material(bpy,'Path grit and small stones',(.30,.27,.22),roughness=.82)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=180.;noise.inputs['Detail'].default_value=8\n    links.new(coord.outputs['Object'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position=.28;ramp.color_ramp.elements[0].color=(.085,.078,.064,1)\n    ramp.color_ramp.elements[1].position=.74;ramp.color_ramp.elements[1].color=(.52,.48,.41,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    tint=nodes.new('ShaderNodeVertexColor');tint.layer_name='stone_tint'\n    albedo=_mix(nodes,links,1.,ramp.outputs['Color'],tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.55;bump.inputs['Distance'].default_value=.003\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef _unit_stone(rings=4,segments=7):\n    \"\"\"Angular, cheap, and irregular once squashed: reads as grit, not a ball.\"\"\"\n    vertices=[(0.,0.,1.)];faces=[]\n    for ring in range(1,rings):\n        phi=math.pi*ring/rings;radius=math.sin(phi);z=math.cos(phi)\n        for segment in range(segments):\n            theta=2*math.pi*segment/segments\n            vertices.append((radius*math.cos(theta),radius*math.sin(theta),z))\n    vertices.append((0.,0.,-1.));south=len(vertices)-1\n    for segment in range(segments):\n        faces.append((0,1+segment,1+(segment+1)%segments))\n    for ring in range(rings-2):\n        for segment in range(segments):\n            a=1+ring*segments+segment;b=1+ring*segments+(segment+1)%segments\n            faces.extend([(a,b,b+segments),(a,b+segments,a+segments)])\n    base=1+(rings-2)*segments\n    for segment in range(segments):\n        faces.append((south,base+(segment+1)%segments,base+segment))\n    return vertices,faces\n\ndef scatter_gravel(bpy,c,frames,path_half_width=1.90,count=520,seed=517):\n    \"\"\"Loose grit and small stones lying on the path.\n\n    Decorative only: every stone is rejected if it lands inside the corridor the\n    ball sweeps, so the visible surface never contradicts the simulated contact\n    geometry. Placement is seeded, so a rerun reproduces the same stones.\n    \"\"\"\n    from scene_support.uneven_ground_ball.terrain_geometry import height\n    rng=random.Random(seed)\n    template,template_faces=_unit_stone()\n    trajectory=[(frame['ball']['location'][0],frame['ball']['location'][1]) for frame in frames]\n    clearance=c['ball_radius']+.09\n    vertices=[];faces=[];tints=[];placed=0\n    for _ in range(count*4):\n        if placed>=count:break\n        x=rng.uniform(-3.6,3.1);y=rng.uniform(-2.1,2.1)\n        if min(math.hypot(x-tx,y-ty) for tx,ty in trajectory)<clearance:continue\n        z=float(height(x,y,c))\n        roll=rng.random()\n        size=rng.uniform(.009,.026) if roll<.90 else rng.uniform(.030,.058)\n        squash=rng.uniform(.40,.60);spin=rng.uniform(0,2*math.pi);tilt=rng.uniform(-.40,.40)\n        ca,sa,ct,st=math.cos(spin),math.sin(spin),math.cos(tilt),math.sin(tilt)\n        shade=rng.uniform(.48,1.12);warmth=rng.uniform(.92,1.12)\n        tint=(shade*warmth,shade,shade/warmth,1.)\n        base_vertices=len(vertices)\n        for vx,vy,vz in template:\n            # tilt, then spin, then squash, then settle into the ground\n            ty,tz=vy*ct-vz*st,vy*st+vz*ct\n            fx,fy=vx*ca-ty*sa,vx*sa+ty*ca\n            vertices.append((x+fx*size,y+fy*size,z+tz*size*squash-size*squash*.42))\n            tints.append(tint)\n        for corner in template_faces:\n            faces.append(tuple(base_vertices+index for index in corner))\n        placed+=1\n    mesh=bpy.data.meshes.new('Loose grit');mesh.from_pydata(vertices,[],faces);mesh.update()\n    attribute=mesh.color_attributes.new(name='stone_tint',type='FLOAT_COLOR',domain='POINT')\n    attribute.data.foreach_set('color',__import__('numpy').asarray(tints,dtype='float32').ravel())\n    stones=bpy.data.objects.new('Loose grit on path',mesh);bpy.context.scene.collection.objects.link(stones)\n    stones.data.materials.append(stone_material(bpy))\n    return placed\n\ndef build_lighting(bpy,scene):\n    \"\"\"One low raking sun for relief, plus sky and soft bounce fills.\n\n    A diffuse dome from above renders a rutted path as flat colour; the whole\n    point here is that a low sun throws a shadow across every crest.\n    \"\"\"\n    sun_target=(.85,-.25,.10);sun_from=(5.00,.05,.95)\n    bpy.ops.object.light_add(type='SUN');sun=bpy.context.object;sun.name='Low raking sun'\n    sun.data.energy=5.0;sun.data.angle=.018;sun.data.color=(1.,.83,.63);sun.data.use_shadow=True\n    if hasattr(sun.data,'shadow_maximum_resolution'):sun.data.shadow_maximum_resolution=.0002\n    sun.rotation_euler=_aim(sun_target,sun_from)\n    for name,location,power,size,color in [('Sky bounce',[-1.9,-3.2,2.6],13,4.5,(.66,.78,1.)),\n                                           ('Warm bounce',[.6,2.6,1.1],6,3.2,(1.,.86,.70))]:\n        bpy.ops.object.light_add(type='AREA',location=location);light=bpy.context.object;light.name=name\n        light.data.energy=power;light.data.shape='DISK';light.data.size=size;light.data.color=color;light.data.use_shadow=True\n        light.rotation_euler=_aim((.7,.4,.12),location)\n    return sun\n\ndef _aim(target,source):\n    from mathutils import Vector\n    return (Vector(target)-Vector(source)).to_track_quat('-Z','Y').to_euler()\n", "terrain_geometry": "\"\"\"A continuous terrain mesh shared by collision, rendering and diagnostics.\n\nThe height field is the single source of truth: the collision mesh handed to\npybullet, the render mesh and the ground-truth archive are all built from it, so\nwhat the camera sees is exactly what the ball touches.\n\nRelief is layered on purpose:\n  * a global grade along +x (the path falls away as the ball travels),\n  * named features (wheel ruts, a crown between them, mounds, a pothole) whose\n    footprint is several times the 5 cm mesh spacing, so the mesh represents\n    them faithfully,\n  * a fractal octave stack for the irregular small undulation of packed earth.\n\nAnything finer than roughly two mesh cells cannot be represented by vertices and\nis deliberately left to the material's normal/displacement maps, which change\nshading only and never move the collision surface.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport numpy as np\nimport hashlib\n\n# wavelength (m), amplitude (m), azimuth (deg), phase (rad).\n# The ratios are deliberately irrational so the sum does not read as corrugation.\n# Most of the energy sits between 0.2 m and 1 m: that is the band a 0.10 m ball\n# actually feels and the band a camera at 3 m actually sees.\nOCTAVES=((2.30,.0210,12,.31),(1.35,.0200,64,2.05),(.86,.0240,29,4.13),\n         (.55,.0170,101,1.62),(.34,.0110,47,5.07),(.21,.0062,139,3.41))\n\ndef _fractal(x,y,roughness):\n    \"\"\"Domain-warped octave stack: irregular, deterministic, no RNG.\"\"\"\n    z=np.zeros_like(np.asarray(x,dtype=float))\n    for wavelength,amplitude,azimuth,phase in OCTAVES:\n        k=2*np.pi/wavelength;theta=np.radians(azimuth);kx,ky=k*np.cos(theta),k*np.sin(theta)\n        warp=np.sin(.61*kx*x-1.27*ky*y+.87)\n        z=z+amplitude*np.sin(kx*x+ky*y+phase+warp)\n    return roughness*z\n\ndef height(x,y,c):\n    x=np.asarray(x,dtype=float);y=np.asarray(y,dtype=float)\n    z=c['terrain_base_height']+c['terrain_slope']*x\n    for cx,cy,amplitude,sx,sy in c['bumps']:\n        z=z+amplitude*np.exp(-.5*(((x-cx)/sx)**2+((y-cy)/sy)**2))\n    return z+_fractal(x,y,c['terrain_roughness'])\n\ndef normal(x,y,c):\n    eps=1e-4;dx=(height(x+eps,y,c)-height(x-eps,y,c))/(2*eps);dy=(height(x,y+eps,c)-height(x,y-eps,c))/(2*eps)\n    n=np.array([-float(dx),-float(dy),1.]);return n/np.linalg.norm(n)\n\ndef curvature(x,y,c,h=.05):\n    \"\"\"Laplacian of the height field: negative in hollows, positive on crests.\n\n    Used by the ground material to settle dust into dips and wear the crests,\n    which is what makes relief readable long before lighting does.\n    \"\"\"\n    lap=height(x+h,y,c)+height(x-h,y,c)+height(x,y+h,c)+height(x,y-h,c)-4*height(x,y,c)\n    return lap/(h*h)\n\ndef terrain_mesh(c):\n    lo,hi=c['terrain_bounds'];nx,ny=c['terrain_cells'];xs=np.linspace(lo[0],hi[0],nx+1);ys=np.linspace(lo[1],hi[1],ny+1)\n    x,y=np.meshgrid(xs,ys,indexing='ij');v=np.column_stack((x.ravel(),y.ravel(),height(x,y,c).ravel()))\n    faces=[]\n    for i in range(nx):\n        for j in range(ny):\n            a=i*(ny+1)+j;b=a+ny+1\n            faces.extend([(a,b,b+1),(a,b+1,a+1)])\n    f=np.asarray(faces,dtype=np.int32)\n    return v,f\n\ndef mesh_hash(v,f):return hashlib.sha256(np.asarray(v,dtype=np.float64).tobytes()+np.asarray(f,dtype=np.int32).tobytes()).hexdigest()\n\ndef initial_state(c):\n    x,y=c['ball_start_xy'];n=normal(x,y,c);pos=np.array([x,y,float(height(x,y,c))])+(c['ball_radius']+.0015)*n\n    direction=np.array([1.,0,0]);direction-=np.dot(direction,n)*n;direction/=np.linalg.norm(direction)\n    velocity=c['ball_speed']*direction;omega=np.cross(n,velocity)/c['ball_radius']\n    return pos,velocity,omega\n\ndef environment_boxes(c):\n    parts=[]\n    def add(name,location,size,kind):parts.append(dict(name=name,location=location,size=size,kind=kind))\n    h=float(height(.3,2.62,c))\n    add('Garden bench seat',[.3,2.62,h+.44],[1.4,.42,.07],'wood')\n    add('Garden bench back',[.3,2.81,h+.70],[1.4,.05,.30],'wood')\n    for x in (-.24,.84):\n        for y in (2.48,2.76):\n            foot=float(height(x,y,c));length=h+.405-foot\n            add('Bench leg',[x,y,foot+length/2],[.055,.055,length],'wood')\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));add('Terracotta planter',[x,2.55,z+.16],[.38,.36,.32],'pot')\n    for x in np.linspace(-2.8,6.6,40):\n        z=float(height(x,3.1,c));add('Garden fence slat',[float(x),3.1,z+.40],[.15,.035,.80],'wood')\n    return parts\n", "video_presentation": "\"\"\"Clearly label display-only terrain guides without modifying simulated geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport shutil\nimport numpy as np\nfrom PIL import Image,ImageDraw,ImageFont\nimport imageio.v2 as imageio\n\ndef caption(pixels,gt,index):\n    picture=Image.fromarray(pixels).convert('RGBA');overlay=Image.new('RGBA',picture.size)\n    draw=ImageDraw.Draw(overlay);width,height=picture.size;size=max(12,round(17*width/960))\n    try:font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',size)\n    except OSError:font=ImageFont.load_default()\n    guide=gt['scenario']['render'].get('surface_guide','none')\n    view=gt['scenario']['render'].get('view','terrain')\n    text='2 cm relief contours | display guide; geometry unchanged' if guide=='contours' else 'Low raking sunlight | ground = simulated collision mesh'\n    bar_height=max(30,round(36*width/960));draw.rectangle((0,0,width,bar_height),fill=(18,25,28,205))\n    draw.text((14,8),text,font=font,fill=(245,235,211,255))\n    time=gt['frames'][index]['time_sec'];slow=gt['slow_motion'];speed='real speed' if slow==1 else f'{slow}x slow'\n    right=f't={time:.2f}s | {speed}';draw.text((width-draw.textbbox((0,0),right,font=font)[2]-14,8),right,font=font,fill=(236,196,124,255))\n    return np.asarray(Image.alpha_composite(picture,overlay).convert('RGB'))\n\ndef label_outputs(out,gt,preview_frame,animation=False):\n    out=Path(out);raw=out/'preview_unlabelled.png';shutil.copy2(out/'preview.png',raw)\n    with Image.open(raw) as picture:Image.fromarray(caption(np.asarray(picture.convert('RGB')),gt,preview_frame-1)).save(out/'preview.png')\n    if animation:\n        reader=imageio.get_reader(out/'uneven_ground_ball.mp4')\n        try:\n            with imageio.get_writer(out/'video.mp4',fps=gt['fps'],codec='libx264',quality=8,macro_block_size=1) as writer:\n                for i,pixels in enumerate(reader):writer.append_data(caption(pixels,gt,i))\n        finally:reader.close()\n", "uneven_ground_ball.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os,sys\nfrom pathlib import Path\n\nROOT=_PCVE_ROOT\n_dll_handles=[]\nif os.name=='nt':\n    directory=Path(sys.prefix)/'Library/bin'\n    if directory.exists():_dll_handles.append(os.add_dll_directory(str(directory)))\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "uneven_ground_ball.scene_config": "\"\"\"A ball rolling over a rutted, sloping earth path. SI units.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport math\n\nSCENE_NAME='uneven_ground_ball'\nTOTAL_FRAMES=72\n# Low, near-grazing three-quarter view: the horizon line sits close to the ball,\n# so every crest and hollow of the path breaks the silhouette instead of being\n# flattened into a top-down texture.\nTERRAIN_CAMERA=dict(location=[-0.50,-2.20,.66],target=[-0.50,-.10,.10],lens_mm=26)\nBASELINE_PHYSICS=dict(gravity=[0,0,-9.81],ball_radius=.10,ball_mass=.45,ball_speed=1.4,ball_inertia_factor=.64,\n    ball_start_xy=[-1.8,-.20],ball_friction=.35,ball_rolling_friction=.0015,\n    ball_restitution=.05,ground_friction=1.,substeps=40,solver_iterations=100,\n    terrain_bounds=[[-8.,-8.],[12.,8.]],terrain_cells=[400,320],\n    terrain_base_height=.08,terrain_slope=-.016,terrain_roughness=1.,    # cx, cy, amplitude, sigma_x, sigma_y. Negative amplitude is a hollow.\n    # A broad worn trough carries the ball along +x; discrete mounds and hollows\n    # inside and beside it make the path wander without throwing the ball off it.\n    bumps=[[-.30,-.30,-.040,2.40,.50],\n           [.90,-.50,-.045,.340,.300],\n           [.60,.25,.045,.400,.300],\n           [-1.20,-.45,-.040,.300,.280],\n           [1.80,-.20,.040,.400,.340]])\n\ndef defaults():\n    return dict(schema_version=1,scene=SCENE_NAME,physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24,duration_sec=3.,slow_motion=1,resolution=[960,540],samples=16),\n        camera=dict(location=[-0.55,-2.95,3.6],target=[.75,-.15,.1],lens_mm=35))\n\ndef merge(base,overrides):\n    result=deepcopy(base)\n    for key,value in overrides.items():result[key]=merge(result[key],value) if isinstance(value,dict) else deepcopy(value)\n    return result\n\ndef validate(s):\n    if set(s)-{'schema_version','scene','physics','render','camera','seed'}:raise ValueError('Unknown scenario field; nest physics overrides under physics')\n    c=s['physics'];r=s['render']\n    if set(c)-set(BASELINE_PHYSICS):raise ValueError('Unknown physics parameter')\n    for key in ('ball_radius','ball_mass','ball_inertia_factor','ground_friction','substeps','solver_iterations'):\n        if not math.isfinite(c[key]) or c[key]<=0:raise ValueError(f'{key} must be positive and finite')\n    for key in ('ball_speed','ball_friction','ball_rolling_friction','terrain_roughness'):\n        if not math.isfinite(c[key]) or c[key]<0:raise ValueError(f'{key} must be nonnegative and finite')\n    if not 0<=c['ball_restitution']<=1:raise ValueError('Invalid restitution')\n    if len(c['gravity'])!=3 or not all(math.isfinite(v) for v in c['gravity']):raise ValueError('Invalid gravity')\n    lo,hi=c['terrain_bounds']\n    if len(lo)!=2 or len(hi)!=2 or any(not math.isfinite(v) for v in lo+hi) or any(a>=b for a,b in zip(lo,hi)):raise ValueError('Invalid ground bounds')\n    if len(c['terrain_cells'])!=2 or any(n<2 or n!=int(n) for n in c['terrain_cells']):raise ValueError('Invalid terrain discretization')\n    if len(c['ball_start_xy'])!=2 or any(not a+c['ball_radius']<v<b-c['ball_radius'] for a,b,v in zip(lo,hi,c['ball_start_xy'])):raise ValueError('Ball starts outside terrain')\n    for bump in c['bumps']:\n        if len(bump)!=5 or not all(math.isfinite(v) for v in bump) or min(bump[3:])<=0:raise ValueError('Invalid terrain bump')\n    if r['fps']<=0 or r['duration_sec']<=0 or r['slow_motion'] not in (1,2,4,8) or c['substeps']%r['slow_motion']:raise ValueError('Invalid sampling or slow motion')\n", "uneven_ground_ball.scene_environment": "\"\"\"Courtyard environment and physically based ground shading.\n\nThe ground is the simulation mesh itself: nothing here moves a vertex. Real\nmaterial response (albedo, roughness, normal, ambient occlusion) comes from CC0\nPoly Haven texture sets, which supply exactly the sub-centimetre relief the 5 cm\ncollision grid cannot carry. When a texture set is missing the material degrades\nto the earlier procedural look instead of failing.\n\nThree physics-neutral cues make the undulation read:\n  1. a low raking sun, so every crest throws a shadow into the trough beside it,\n  2. baked cavity/slope tint from the height field itself (dust settles in\n     hollows, crests are scuffed bare),\n  3. normal and displacement maps at sub-mesh scale.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport json,math,random\n\nHERE=_PCVE_ROOT/'assets'/'polyhaven'/'uneven_ground_ball'\n# Same location and naming as the other scenes in /scripts: <asset>_<channel>_<res>.jpg\nASSETS=HERE\nPATH_TEXTURE='floor_pebbles_01'\nGRASS_TEXTURE='grass_ground'\nRESOLUTION='2k'\nCHANNELS=('diff','disp','nor_gl','rough','ao')\n\ndef material(bpy,name,color,metal=0,roughness=.5):\n    mat=bpy.data.materials.new(name);mat.diffuse_color=(*color,1);mat.use_nodes=True\n    shader=mat.node_tree.nodes.get('Principled BSDF')\n    shader.inputs['Base Color'].default_value=(*color,1);shader.inputs['Metallic'].default_value=metal;shader.inputs['Roughness'].default_value=roughness\n    return mat\n\ndef wood(bpy,name,light=(.40,.24,.115),dark=(.20,.095,.038)):\n    mat=material(bpy,name,light,roughness=.48);nodes=mat.node_tree.nodes;links=mat.node_tree.links\n    coords=nodes.new('ShaderNodeTexCoord');scale=nodes.new('ShaderNodeVectorMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=(2,95,5)\n    links.new(coords.outputs['Generated'],scale.inputs[0]);noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=2.5;noise.inputs['Detail'].default_value=3\n    links.new(scale.outputs[0],noise.inputs['Vector']);ramp=nodes.new('ShaderNodeValToRGB');ramp.color_ramp.elements[0].color=(*dark,1);ramp.color_ramp.elements[1].color=(*light,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0]);shader=nodes.get('Principled BSDF');links.new(ramp.outputs['Color'],shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.16;bump.inputs['Distance'].default_value=.0007\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal']);return mat\n\ndef box(bpy,name,location,size,mat,pitch=0,bevel=0):\n    bpy.ops.mesh.primitive_cube_add(size=1,location=location);obj=bpy.context.object;obj.name=name;obj.dimensions=size\n    bpy.ops.object.transform_apply(location=False,rotation=False,scale=True);obj.rotation_euler[1]=pitch;obj.data.materials.append(mat)\n    if bevel:\n        mod=obj.modifiers.new('Manufactured edge','BEVEL');mod.width=bevel;mod.segments=3;obj.modifiers.new('Weighted normals','WEIGHTED_NORMAL')\n    return obj\n\ndef load_texture_set(bpy,asset,resolution=RESOLUTION):\n    \"\"\"Return {channel: bpy.types.Image} for a fetched Poly Haven set, or {}.\"\"\"\n    images={}\n    for channel in CHANNELS:\n        path=ASSETS/f'{asset}_{channel}_{resolution}.jpg'\n        if not path.exists():continue\n        image=bpy.data.images.load(str(path),check_existing=True)\n        image.colorspace_settings.name='sRGB' if channel=='diff' else 'Non-Color'\n        images[channel]=image\n    return images\n\ndef _mix(nodes,links,factor,first,second,blend='MIX'):\n    \"\"\"MixRGB that accepts either a socket, an RGB tuple, or a numeric factor.\"\"\"\n    node=nodes.new('ShaderNodeMixRGB');node.blend_type=blend\n    if isinstance(factor,(int,float)):node.inputs[0].default_value=factor\n    else:links.new(factor,node.inputs[0])\n    for source,index in ((first,1),(second,2)):\n        if isinstance(source,tuple):\n            node.inputs[index].default_value=tuple(source)+(1.,)*(4-len(source)) if len(source)<4 else source\n        else:links.new(source,node.inputs[index])\n    return node.outputs['Color']\n\ndef _samplers(nodes,links,uv,images,metres_per_tile,label):\n    \"\"\"One mapping per texture set; every channel shares it so tiling is exact.\"\"\"\n    mapping=nodes.new('ShaderNodeMapping');mapping.vector_type='POINT'\n    mapping.inputs['Scale'].default_value=(1/metres_per_tile,)*3\n    links.new(uv,mapping.inputs['Vector'])\n    out={}\n    for channel,image in images.items():\n        sampler=nodes.new('ShaderNodeTexImage');sampler.image=image\n        sampler.label=f'{label} {channel} ({metres_per_tile:g} m per tile)'\n        links.new(mapping.outputs['Vector'],sampler.inputs['Vector'])\n        out[channel]=sampler.outputs['Color']\n    return out\n\ndef ground_material(bpy,c,guide='none',path_asset=PATH_TEXTURE,grass_asset=GRASS_TEXTURE,\n                    path_half_width=1.90,edge_width=.34,vertex_tint='terrain_shading'):\n    path=load_texture_set(bpy,path_asset);grass=load_texture_set(bpy,grass_asset)\n    mat=material(bpy,'Weathered courtyard path',(.36,.30,.22),roughness=.85)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    uv=nodes.new('ShaderNodeTexCoord').outputs['UV']\n    separate=nodes.new('ShaderNodeSeparateXYZ');links.new(uv,separate.inputs[0])\n    path_sources=_samplers(nodes,links,uv,path,.62,'path') if path else {}\n    grass_sources=_samplers(nodes,links,uv,grass,.42,'lawn') if grass else {}\n\n    # --- worn path / lawn boundary, broken up so the edge is never a straight line\n    boundary=nodes.new('ShaderNodeTexNoise');boundary.inputs['Scale'].default_value=2.6;boundary.inputs['Detail'].default_value=5\n    links.new(uv,boundary.inputs['Vector'])\n    wobble=nodes.new('ShaderNodeMath');wobble.operation='MULTIPLY';wobble.inputs[1].default_value=.42\n    links.new(boundary.outputs['Fac'],wobble.inputs[0])\n    absolute_y=nodes.new('ShaderNodeMath');absolute_y.operation='ABSOLUTE';links.new(separate.outputs['Y'],absolute_y.inputs[0])\n    shifted=nodes.new('ShaderNodeMath');shifted.operation='ADD'\n    links.new(absolute_y.outputs[0],shifted.inputs[0]);links.new(wobble.outputs[0],shifted.inputs[1])\n    is_lawn=nodes.new('ShaderNodeMapRange');is_lawn.interpolation_type='SMOOTHSTEP'\n    is_lawn.inputs['From Min'].default_value=path_half_width;is_lawn.inputs['From Max'].default_value=path_half_width+edge_width\n    links.new(shifted.outputs[0],is_lawn.inputs['Value'])\n    lawn=is_lawn.outputs['Result']\n\n    if path_sources:\n        # Damp/dry patches: one much coarser noise multiply kills the obvious repeat.\n        macro=nodes.new('ShaderNodeTexNoise');macro.inputs['Scale'].default_value=.38;macro.inputs['Detail'].default_value=4\n        stretch=nodes.new('ShaderNodeVectorMath');stretch.operation='MULTIPLY';stretch.inputs[1].default_value=(1.6,.85,1.)\n        links.new(uv,stretch.inputs[0]);links.new(stretch.outputs[0],macro.inputs['Vector'])\n        macro_ramp=nodes.new('ShaderNodeValToRGB')\n        macro_ramp.color_ramp.elements[0].position=.32;macro_ramp.color_ramp.elements[0].color=(.74,.68,.60,1)\n        macro_ramp.color_ramp.elements[1].position=.70;macro_ramp.color_ramp.elements[1].color=(1.08,1.04,.97,1)\n        links.new(macro.outputs['Fac'],macro_ramp.inputs[0])\n        path_colour=_mix(nodes,links,1.,path_sources['diff'],macro_ramp.outputs['Color'],'MULTIPLY')\n        path_rough=path_sources.get('rough',(.72,.72,.72))\n        path_height=path_sources.get('disp',(.5,.5,.5))\n        path_normal=path_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=5.;noise.inputs['Detail'].default_value=3\n        links.new(uv,noise.inputs['Vector'])\n        path_colour=_mix(nodes,links,noise.outputs['Fac'],(.175,.145,.105,1),(.31,.255,.185,1))\n        path_rough=path_height=path_normal=(.5,.5,.5);path_normal=(.5,.5,1.)\n\n    if grass_sources:\n        # The scanned lawn is dark olive; push it towards living turf so the path\n        # edge reads as earth-versus-grass instead of two similar browns.\n        grass_colour=_mix(nodes,links,1.,grass_sources['diff'],(1.0,1.16,.80),'MULTIPLY')\n        grass_rough=grass_sources.get('rough',(.80,.80,.80))\n        grass_height=grass_sources.get('disp',(.5,.5,.5))\n        grass_normal=grass_sources.get('nor_gl',(.5,.5,1.))\n    else:\n        noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=9.;noise.inputs['Detail'].default_value=6\n        links.new(uv,noise.inputs['Vector'])\n        grass_colour=_mix(nodes,links,noise.outputs['Fac'],(.045,.085,.028,1),(.135,.195,.055,1))\n        grass_rough=(.86,.86,.86);grass_height=(.5,.5,.5);grass_normal=(.5,.5,1.)\n\n    albedo=_mix(nodes,links,lawn,path_colour,grass_colour)\n    if path_sources.get('ao') or grass_sources.get('ao'):\n        occlusion=_mix(nodes,links,lawn,path_sources.get('ao',(1.,1.,1.)),grass_sources.get('ao',(1.,1.,1.)))\n        albedo=_mix(nodes,links,.75,albedo,occlusion,'MULTIPLY')\n    if vertex_tint:\n        tint=nodes.new('ShaderNodeVertexColor');tint.layer_name=vertex_tint\n        albedo=_mix(nodes,links,1.,albedo,tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n\n    span=nodes.new('ShaderNodeMapRange');span.inputs['To Min'].default_value=.58;span.inputs['To Max'].default_value=.97\n    links.new(_mix(nodes,links,lawn,path_rough,grass_rough),span.inputs['Value'])\n    links.new(span.outputs['Result'],shader.inputs['Roughness'])\n\n    # --- micro relief: mixed tangent-space normals, then the height map ------\n    normal_map=nodes.new('ShaderNodeNormalMap');normal_map.inputs['Strength'].default_value=.9;normal_map.space='TANGENT'\n    normal_map.uv_map='World metres'\n    links.new(_mix(nodes,links,lawn,path_normal,grass_normal),normal_map.inputs['Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.95;bump.inputs['Distance'].default_value=.02\n    links.new(_mix(nodes,links,lawn,path_height,grass_height),bump.inputs['Height'])\n    links.new(normal_map.outputs['Normal'],bump.inputs['Normal'])\n    links.new(bump.outputs['Normal'],shader.inputs['Normal'])\n\n    if guide=='contours':\n        position=nodes.new('ShaderNodeNewGeometry');xyz=nodes.new('ShaderNodeSeparateXYZ');links.new(position.outputs['Position'],xyz.inputs[0])\n        grade=nodes.new('ShaderNodeMath');grade.operation='MULTIPLY';grade.inputs[1].default_value=c['terrain_slope'];links.new(xyz.outputs['X'],grade.inputs[0])\n        subtract=nodes.new('ShaderNodeMath');subtract.operation='SUBTRACT';links.new(xyz.outputs['Z'],subtract.inputs[0]);links.new(grade.outputs[0],subtract.inputs[1])\n        baseline=nodes.new('ShaderNodeMath');baseline.operation='SUBTRACT';baseline.inputs[1].default_value=c['terrain_base_height'];links.new(subtract.outputs[0],baseline.inputs[0])\n        scale=nodes.new('ShaderNodeMath');scale.operation='MULTIPLY';scale.inputs[1].default_value=50.;links.new(baseline.outputs[0],scale.inputs[0])\n        repeat=nodes.new('ShaderNodeMath');repeat.operation='PINGPONG';repeat.inputs[1].default_value=.5;links.new(scale.outputs[0],repeat.inputs[0])\n        threshold=nodes.new('ShaderNodeMath');threshold.operation='LESS_THAN';threshold.inputs[1].default_value=.016;links.new(repeat.outputs[0],threshold.inputs[0])\n        overlay=nodes.new('ShaderNodeMixRGB');overlay.blend_type='MIX'\n        links.new(albedo,overlay.inputs[1]);overlay.inputs[2].default_value=(.03,.09,.10,1)\n        links.new(threshold.outputs[0],overlay.inputs[0])\n        links.new(overlay.outputs['Color'],shader.inputs['Base Color'])\n    return mat\n\ndef bake_terrain_shading(mesh,vertices,c):\n    \"\"\"Bake cavity and slope into a colour attribute: shading data, not geometry.\n\n    Hollows collect damp fine material and read darker; exposed crests are\n    scuffed lighter. The tint is derived from the same height field the ball\n    collides with, so it cannot contradict the motion.\n    \"\"\"\n    import numpy as np\n    from scene_support.uneven_ground_ball.terrain_geometry import curvature\n    x=vertices[:,0];y=vertices[:,1]\n    lap=curvature(x,y,c)\n    # Positive Laplacian = hollow (surface curves up around the point).\n    cavity=np.clip(lap/6.,-1.,1.)\n    brightness=1.-.34*cavity\n    warm=np.clip(-cavity,0.,1.)\n    tint=np.stack((brightness+.05*warm,brightness,brightness-.06*warm),axis=1)\n    tint=np.clip(tint,0.,2.2)\n    attribute=mesh.color_attributes.new(name='terrain_shading',type='FLOAT_COLOR',domain='POINT')\n    rgba=np.concatenate((tint,np.ones((len(tint),1))),axis=1)\n    attribute.data.foreach_set('color',rgba.astype(np.float32).ravel())\n    return tint\n\ndef ball_material(bpy):\n    mat=material(bpy,'Orange and ivory rubber ball',(.74,.20,.035),roughness=.55)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');sep=nodes.new('ShaderNodeSeparateXYZ');links.new(coord.outputs['Generated'],sep.inputs[0])\n    centred=[]\n    for axis in ('X','Y'):\n        node=nodes.new('ShaderNodeMath');node.operation='SUBTRACT';node.inputs[1].default_value=.5;links.new(sep.outputs[axis],node.inputs[0]);centred.append(node)\n    angle=nodes.new('ShaderNodeMath');angle.operation='ARCTAN2';links.new(centred[1].outputs[0],angle.inputs[0]);links.new(centred[0].outputs[0],angle.inputs[1])\n    freq=nodes.new('ShaderNodeMath');freq.operation='MULTIPLY';freq.inputs[1].default_value=2;links.new(angle.outputs[0],freq.inputs[0])\n    wave=nodes.new('ShaderNodeMath');wave.operation='SINE';links.new(freq.outputs[0],wave.inputs[0]);split=nodes.new('ShaderNodeMath');split.operation='GREATER_THAN';links.new(wave.outputs[0],split.inputs[0])\n    mix=nodes.new('ShaderNodeMixRGB');mix.inputs[1].default_value=(.72,.16,.025,1);mix.inputs[2].default_value=(.87,.82,.66,1);links.new(split.outputs[0],mix.inputs[0]);links.new(mix.outputs[0],shader.inputs['Base Color'])\n    for name,value in (('Coat Weight',.25),('Coat Roughness',.28)):\n        if name in shader.inputs:shader.inputs[name].default_value=value\n    noise=nodes.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=220.;links.new(coord.outputs['Generated'],noise.inputs['Vector'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.14;bump.inputs['Distance'].default_value=.00018;links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef build_environment(bpy,c,path_half_width=1.90):\n    from scene_support.uneven_ground_ball.terrain_geometry import environment_boxes,height\n    timber=wood(bpy,'Oiled garden timber',(.31,.16,.065),(.095,.040,.016));pot=material(bpy,'Terracotta planter',(.43,.20,.095),roughness=.9)\n    for part in environment_boxes(c):box(bpy,part['name'],part['location'],part['size'],pot if part['kind']=='pot' else timber,bevel=.005)\n    soil=material(bpy,'Planter soil',(.08,.055,.025),roughness=1);leaves=material(bpy,'Garden herbs',(.10,.26,.075),roughness=.9)\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));box(bpy,'Soil in planter',[x,2.55,z+.322],[.34,.32,.012],soil)\n        for i in range(7):\n            angle=2*math.pi*i/7\n            bpy.ops.mesh.primitive_uv_sphere_add(segments=12,ring_count=8,radius=1,location=[x+.10*math.cos(angle),2.55+.08*math.sin(angle),z+.40+.04*(i%2)])\n            leaf=bpy.context.object;leaf.name='Herb cluster';leaf.scale=(.09,.07,.14);leaf.data.materials.append(leaves)\n            for face in leaf.data.polygons:face.use_smooth=True\n    # Fine grass blades are decorative vegetation, kept clear of the rolling path.\n    rng=random.Random(418);vertices=[];faces=[]\n    for _ in range(2600):\n        x=rng.uniform(-3.4,6.6);y=rng.choice((-1,1))*rng.uniform(path_half_width+.22,3.05);z=float(height(x,y,c))\n        angle=rng.uniform(0,2*math.pi);width=rng.uniform(.003,.006);length=rng.uniform(.014,.040)\n        dx=width*math.cos(angle);dy=width*math.sin(angle);start=len(vertices)\n        vertices.extend([(x-dx,y-dy,z),(x+dx,y+dy,z),(x+.006*math.cos(angle+.7),y+.006*math.sin(angle+.7),z+length)])\n        faces.append((start,start+1,start+2))\n    mesh=bpy.data.meshes.new('Garden grass blades');mesh.from_pydata(vertices,[],faces);mesh.update()\n    grass=bpy.data.objects.new('Grass around path',mesh);bpy.context.scene.collection.objects.link(grass);grass.data.materials.append(material(bpy,'Grass blades',(.085,.175,.038),roughness=.9))\n\ndef stone_material(bpy):\n    mat=material(bpy,'Path grit and small stones',(.30,.27,.22),roughness=.82)\n    nodes,links=mat.node_tree.nodes,mat.node_tree.links;shader=nodes.get('Principled BSDF')\n    coord=nodes.new('ShaderNodeTexCoord');noise=nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value=180.;noise.inputs['Detail'].default_value=8\n    links.new(coord.outputs['Object'],noise.inputs['Vector'])\n    ramp=nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position=.28;ramp.color_ramp.elements[0].color=(.085,.078,.064,1)\n    ramp.color_ramp.elements[1].position=.74;ramp.color_ramp.elements[1].color=(.52,.48,.41,1)\n    links.new(noise.outputs['Fac'],ramp.inputs[0])\n    tint=nodes.new('ShaderNodeVertexColor');tint.layer_name='stone_tint'\n    albedo=_mix(nodes,links,1.,ramp.outputs['Color'],tint.outputs['Color'],'MULTIPLY')\n    links.new(albedo,shader.inputs['Base Color'])\n    bump=nodes.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.55;bump.inputs['Distance'].default_value=.003\n    links.new(noise.outputs['Fac'],bump.inputs['Height']);links.new(bump.outputs[0],shader.inputs['Normal'])\n    return mat\n\ndef _unit_stone(rings=4,segments=7):\n    \"\"\"Angular, cheap, and irregular once squashed: reads as grit, not a ball.\"\"\"\n    vertices=[(0.,0.,1.)];faces=[]\n    for ring in range(1,rings):\n        phi=math.pi*ring/rings;radius=math.sin(phi);z=math.cos(phi)\n        for segment in range(segments):\n            theta=2*math.pi*segment/segments\n            vertices.append((radius*math.cos(theta),radius*math.sin(theta),z))\n    vertices.append((0.,0.,-1.));south=len(vertices)-1\n    for segment in range(segments):\n        faces.append((0,1+segment,1+(segment+1)%segments))\n    for ring in range(rings-2):\n        for segment in range(segments):\n            a=1+ring*segments+segment;b=1+ring*segments+(segment+1)%segments\n            faces.extend([(a,b,b+segments),(a,b+segments,a+segments)])\n    base=1+(rings-2)*segments\n    for segment in range(segments):\n        faces.append((south,base+(segment+1)%segments,base+segment))\n    return vertices,faces\n\ndef scatter_gravel(bpy,c,frames,path_half_width=1.90,count=520,seed=517):\n    \"\"\"Loose grit and small stones lying on the path.\n\n    Decorative only: every stone is rejected if it lands inside the corridor the\n    ball sweeps, so the visible surface never contradicts the simulated contact\n    geometry. Placement is seeded, so a rerun reproduces the same stones.\n    \"\"\"\n    from scene_support.uneven_ground_ball.terrain_geometry import height\n    rng=random.Random(seed)\n    template,template_faces=_unit_stone()\n    trajectory=[(frame['ball']['location'][0],frame['ball']['location'][1]) for frame in frames]\n    clearance=c['ball_radius']+.09\n    vertices=[];faces=[];tints=[];placed=0\n    for _ in range(count*4):\n        if placed>=count:break\n        x=rng.uniform(-3.6,3.1);y=rng.uniform(-2.1,2.1)\n        if min(math.hypot(x-tx,y-ty) for tx,ty in trajectory)<clearance:continue\n        z=float(height(x,y,c))\n        roll=rng.random()\n        size=rng.uniform(.009,.026) if roll<.90 else rng.uniform(.030,.058)\n        squash=rng.uniform(.40,.60);spin=rng.uniform(0,2*math.pi);tilt=rng.uniform(-.40,.40)\n        ca,sa,ct,st=math.cos(spin),math.sin(spin),math.cos(tilt),math.sin(tilt)\n        shade=rng.uniform(.48,1.12);warmth=rng.uniform(.92,1.12)\n        tint=(shade*warmth,shade,shade/warmth,1.)\n        base_vertices=len(vertices)\n        for vx,vy,vz in template:\n            # tilt, then spin, then squash, then settle into the ground\n            ty,tz=vy*ct-vz*st,vy*st+vz*ct\n            fx,fy=vx*ca-ty*sa,vx*sa+ty*ca\n            vertices.append((x+fx*size,y+fy*size,z+tz*size*squash-size*squash*.42))\n            tints.append(tint)\n        for corner in template_faces:\n            faces.append(tuple(base_vertices+index for index in corner))\n        placed+=1\n    mesh=bpy.data.meshes.new('Loose grit');mesh.from_pydata(vertices,[],faces);mesh.update()\n    attribute=mesh.color_attributes.new(name='stone_tint',type='FLOAT_COLOR',domain='POINT')\n    attribute.data.foreach_set('color',__import__('numpy').asarray(tints,dtype='float32').ravel())\n    stones=bpy.data.objects.new('Loose grit on path',mesh);bpy.context.scene.collection.objects.link(stones)\n    stones.data.materials.append(stone_material(bpy))\n    return placed\n\ndef build_lighting(bpy,scene):\n    \"\"\"One low raking sun for relief, plus sky and soft bounce fills.\n\n    A diffuse dome from above renders a rutted path as flat colour; the whole\n    point here is that a low sun throws a shadow across every crest.\n    \"\"\"\n    sun_target=(.85,-.25,.10);sun_from=(5.00,.05,.95)\n    bpy.ops.object.light_add(type='SUN');sun=bpy.context.object;sun.name='Low raking sun'\n    sun.data.energy=5.0;sun.data.angle=.018;sun.data.color=(1.,.83,.63);sun.data.use_shadow=True\n    if hasattr(sun.data,'shadow_maximum_resolution'):sun.data.shadow_maximum_resolution=.0002\n    sun.rotation_euler=_aim(sun_target,sun_from)\n    for name,location,power,size,color in [('Sky bounce',[-1.9,-3.2,2.6],13,4.5,(.66,.78,1.)),\n                                           ('Warm bounce',[.6,2.6,1.1],6,3.2,(1.,.86,.70))]:\n        bpy.ops.object.light_add(type='AREA',location=location);light=bpy.context.object;light.name=name\n        light.data.energy=power;light.data.shape='DISK';light.data.size=size;light.data.color=color;light.data.use_shadow=True\n        light.rotation_euler=_aim((.7,.4,.12),location)\n    return sun\n\ndef _aim(target,source):\n    from mathutils import Vector\n    return (Vector(target)-Vector(source)).to_track_quat('-Z','Y').to_euler()\n", "uneven_ground_ball.terrain_geometry": "\"\"\"A continuous terrain mesh shared by collision, rendering and diagnostics.\n\nThe height field is the single source of truth: the collision mesh handed to\npybullet, the render mesh and the ground-truth archive are all built from it, so\nwhat the camera sees is exactly what the ball touches.\n\nRelief is layered on purpose:\n  * a global grade along +x (the path falls away as the ball travels),\n  * named features (wheel ruts, a crown between them, mounds, a pothole) whose\n    footprint is several times the 5 cm mesh spacing, so the mesh represents\n    them faithfully,\n  * a fractal octave stack for the irregular small undulation of packed earth.\n\nAnything finer than roughly two mesh cells cannot be represented by vertices and\nis deliberately left to the material's normal/displacement maps, which change\nshading only and never move the collision surface.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport numpy as np\nimport hashlib\n\n# wavelength (m), amplitude (m), azimuth (deg), phase (rad).\n# The ratios are deliberately irrational so the sum does not read as corrugation.\n# Most of the energy sits between 0.2 m and 1 m: that is the band a 0.10 m ball\n# actually feels and the band a camera at 3 m actually sees.\nOCTAVES=((2.30,.0210,12,.31),(1.35,.0200,64,2.05),(.86,.0240,29,4.13),\n         (.55,.0170,101,1.62),(.34,.0110,47,5.07),(.21,.0062,139,3.41))\n\ndef _fractal(x,y,roughness):\n    \"\"\"Domain-warped octave stack: irregular, deterministic, no RNG.\"\"\"\n    z=np.zeros_like(np.asarray(x,dtype=float))\n    for wavelength,amplitude,azimuth,phase in OCTAVES:\n        k=2*np.pi/wavelength;theta=np.radians(azimuth);kx,ky=k*np.cos(theta),k*np.sin(theta)\n        warp=np.sin(.61*kx*x-1.27*ky*y+.87)\n        z=z+amplitude*np.sin(kx*x+ky*y+phase+warp)\n    return roughness*z\n\ndef height(x,y,c):\n    x=np.asarray(x,dtype=float);y=np.asarray(y,dtype=float)\n    z=c['terrain_base_height']+c['terrain_slope']*x\n    for cx,cy,amplitude,sx,sy in c['bumps']:\n        z=z+amplitude*np.exp(-.5*(((x-cx)/sx)**2+((y-cy)/sy)**2))\n    return z+_fractal(x,y,c['terrain_roughness'])\n\ndef normal(x,y,c):\n    eps=1e-4;dx=(height(x+eps,y,c)-height(x-eps,y,c))/(2*eps);dy=(height(x,y+eps,c)-height(x,y-eps,c))/(2*eps)\n    n=np.array([-float(dx),-float(dy),1.]);return n/np.linalg.norm(n)\n\ndef curvature(x,y,c,h=.05):\n    \"\"\"Laplacian of the height field: negative in hollows, positive on crests.\n\n    Used by the ground material to settle dust into dips and wear the crests,\n    which is what makes relief readable long before lighting does.\n    \"\"\"\n    lap=height(x+h,y,c)+height(x-h,y,c)+height(x,y+h,c)+height(x,y-h,c)-4*height(x,y,c)\n    return lap/(h*h)\n\ndef terrain_mesh(c):\n    lo,hi=c['terrain_bounds'];nx,ny=c['terrain_cells'];xs=np.linspace(lo[0],hi[0],nx+1);ys=np.linspace(lo[1],hi[1],ny+1)\n    x,y=np.meshgrid(xs,ys,indexing='ij');v=np.column_stack((x.ravel(),y.ravel(),height(x,y,c).ravel()))\n    faces=[]\n    for i in range(nx):\n        for j in range(ny):\n            a=i*(ny+1)+j;b=a+ny+1\n            faces.extend([(a,b,b+1),(a,b+1,a+1)])\n    f=np.asarray(faces,dtype=np.int32)\n    return v,f\n\ndef mesh_hash(v,f):return hashlib.sha256(np.asarray(v,dtype=np.float64).tobytes()+np.asarray(f,dtype=np.int32).tobytes()).hexdigest()\n\ndef initial_state(c):\n    x,y=c['ball_start_xy'];n=normal(x,y,c);pos=np.array([x,y,float(height(x,y,c))])+(c['ball_radius']+.0015)*n\n    direction=np.array([1.,0,0]);direction-=np.dot(direction,n)*n;direction/=np.linalg.norm(direction)\n    velocity=c['ball_speed']*direction;omega=np.cross(n,velocity)/c['ball_radius']\n    return pos,velocity,omega\n\ndef environment_boxes(c):\n    parts=[]\n    def add(name,location,size,kind):parts.append(dict(name=name,location=location,size=size,kind=kind))\n    h=float(height(.3,2.62,c))\n    add('Garden bench seat',[.3,2.62,h+.44],[1.4,.42,.07],'wood')\n    add('Garden bench back',[.3,2.81,h+.70],[1.4,.05,.30],'wood')\n    for x in (-.24,.84):\n        for y in (2.48,2.76):\n            foot=float(height(x,y,c));length=h+.405-foot\n            add('Bench leg',[x,y,foot+length/2],[.055,.055,length],'wood')\n    for x in (-1.9,2.9):\n        z=float(height(x,2.55,c));add('Terracotta planter',[x,2.55,z+.16],[.38,.36,.32],'pot')\n    for x in np.linspace(-2.8,6.6,40):\n        z=float(height(x,3.1,c));add('Garden fence slat',[float(x),3.1,z+.40],[.15,.035,.80],'wood')\n    return parts\n", "uneven_ground_ball.video_presentation": "\"\"\"Clearly label display-only terrain guides without modifying simulated geometry.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom pathlib import Path\nimport shutil\nimport numpy as np\nfrom PIL import Image,ImageDraw,ImageFont\nimport imageio.v2 as imageio\n\ndef caption(pixels,gt,index):\n    picture=Image.fromarray(pixels).convert('RGBA');overlay=Image.new('RGBA',picture.size)\n    draw=ImageDraw.Draw(overlay);width,height=picture.size;size=max(12,round(17*width/960))\n    try:font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',size)\n    except OSError:font=ImageFont.load_default()\n    guide=gt['scenario']['render'].get('surface_guide','none')\n    view=gt['scenario']['render'].get('view','terrain')\n    text='2 cm relief contours | display guide; geometry unchanged' if guide=='contours' else 'Low raking sunlight | ground = simulated collision mesh'\n    bar_height=max(30,round(36*width/960));draw.rectangle((0,0,width,bar_height),fill=(18,25,28,205))\n    draw.text((14,8),text,font=font,fill=(245,235,211,255))\n    time=gt['frames'][index]['time_sec'];slow=gt['slow_motion'];speed='real speed' if slow==1 else f'{slow}x slow'\n    right=f't={time:.2f}s | {speed}';draw.text((width-draw.textbbox((0,0),right,font=font)[2]-14,8),right,font=font,fill=(236,196,124,255))\n    return np.asarray(Image.alpha_composite(picture,overlay).convert('RGB'))\n\ndef label_outputs(out,gt,preview_frame,animation=False):\n    out=Path(out);raw=out/'preview_unlabelled.png';shutil.copy2(out/'preview.png',raw)\n    with Image.open(raw) as picture:Image.fromarray(caption(np.asarray(picture.convert('RGB')),gt,preview_frame-1)).save(out/'preview.png')\n    if animation:\n        reader=imageio.get_reader(out/'uneven_ground_ball.mp4')\n        try:\n            with imageio.get_writer(out/'video.mp4',fps=gt['fps'],codec='libx264',quality=8,macro_block_size=1) as writer:\n                for i,pixels in enumerate(reader):writer.append_data(caption(pixels,gt,i))\n        finally:reader.close()\n", "uneven_ground_ball": "\"\"\"Shared support modules for uneven_ground_ball.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'uneven_ground_ball'
_BUNDLE_ALIASES = ['runtime_support', 'scene_config', 'scene_environment', 'terrain_geometry', 'video_presentation', 'uneven_ground_ball', 'uneven_ground_ball.runtime_support', 'uneven_ground_ball.scene_config', 'uneven_ground_ball.scene_environment', 'uneven_ground_ball.terrain_geometry', 'uneven_ground_ball.video_presentation']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['runtime_support', 'scene_config', 'scene_environment', 'terrain_geometry', 'video_presentation'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()




